local PUI = _G.PhoenixUI if not (PUI and PUI.gateOpen) then return end
-- zhCN translations (PUI_V2 5.17). Keys are the English strings Phoenix renders
-- (/pui loc lists coverage; .tools/locales.py writes ../keys.txt, and
-- .tools/locale_tokens.py checks every format spec, escape and slash command
-- survives). Game terms follow the Simplified Chinese client's own wording.
-- Any string not listed falls back to English.
PUI.Locale:Add("zhCN", {
  ["+2 / +3 marks on the timer bar"] = "计时条上的 +2 / +3 标记",
  ["/gg"] = "/gg",
  ["/gg message"] = "/gg 消息",
  ["/keys command"] = "/keys 命令",
  ["/pui council <item> asks your group Need, Minor, Transmog or Pass; answers come back with item level. Others need Phoenix with Council on."] = "/pui council <物品> 向队伍询问需求、小幅提升、幻化或放弃；回复附带物品等级。其他人需要开启 Council 的 Phoenix。",
  ["/pui pull [s] (also /pui cd), /pui break [min], /pui rc."] = "/pui pull [秒]（也可 /pui cd）、/pui break [分钟]、/pui rc。",
  ["/pui rl"] = "/pui rl",
  ["/pui simc opens your character as a SimulationCraft profile, ready to copy into SimulationCraft or Raidbots."] = "/pui simc 将你的角色打开为 SimulationCraft 配置，可直接复制到 SimulationCraft 或 Raidbots。",
  ["0 = off. Errors seen in 3 or more sessions become your baseline; when this many errors outside the baseline happen in one session, one chat line says so (once per session)."] = "0 = 关闭。在 3 次或更多会话中出现的错误成为基线；一次会话中出现这么多基线外错误时，聊天中会有一行提示（每次会话一次）。",
  ["0 keeps the summary card open until you close it."] = "0 表示摘要卡片保持打开，直到你关闭它。",
  ["0 makes the bar background invisible."] = "0 使计量条背景不可见。",
  ["0 poor, 1 common, 2 uncommon, 3 rare, 4 epic, 5 legendary, 6 artifact, 7 heirloom."] = "0 粗糙，1 普通，2 优秀，3 精良，4 史诗，5 传说，6 神器，7 传家宝。",
  ["12.4K instead of 12,400."] = "显示 12.4K 而不是 12,400。",
  ["24-hour clock"] = "24 小时制",
  ["24-hour clock block"] = "24 小时时钟模块",
  ["24-hour time instead of AM/PM."] = "使用 24 小时制而不是上午/下午。",
  ["A 1 px theme border around each skinned button."] = "每个美化按钮周围 1 像素的主题边框。",
  ["A Phoenix button in the inbox that takes only the gold (no items, skips COD) from every mail."] = "收件箱中的 Phoenix 按钮，只从每封邮件中提取金币（不取物品，跳过付款取信）。",
  ["A Phoenix search box: items on the page that do not match fade."] = "Phoenix 搜索框：页面上不匹配的物品会变淡。",
  ["A banner with rising embers when you earn an achievement, time a key or level up. Reduced motion (Glows page) keeps only the banner."] = "获得成就、限时完成钥石或升级时显示带升腾余烬的横幅。减少动画（光效页面）时只保留横幅。",
  ["A bar for spec resources that live in an aura (for example a stacking buff). Set the spell below."] = "用于存放在光环中的专精资源（例如可叠加的增益）的计量条。在下方设置法术。",
  ["A bar glows when the game marks the ability as about to happen (the timing comes from the game)."] = "当游戏标记技能即将发生时计量条发光（时间来自游戏）。",
  ["A bar that counts down to your next melee swing. Off by default; Forever only. It reads your own swings from the combat log."] = "倒数到你下一次近战攻击的计量条。默认关闭；仅限 Forever。从战斗记录读取你自己的攻击。",
  ["A block of extra frames for every tank (or healer) in the group, in addition to the normal frames."] = "为队伍中每个坦克（或治疗）额外显示的一组框体，不影响普通框体。",
  ["A bright edge when absorbs run past full health, and when heal absorbs eat more than the health left."] = "吸收量超过满血时，以及治疗吸收超过剩余生命时显示亮边。",
  ["A bright line where the bar is draining."] = "计量条减少处的亮线。",
  ["A button in Blizzard's Edit Mode window that opens Phoenix Studio."] = "暴雪编辑模式窗口中打开 Phoenix Studio 的按钮。",
  ["A button on the panel that cancels your oldest application, so a new one fits under the limit of five. In combat it waits until combat ends."] = "面板上取消你最早申请的按钮，以便新申请不超过五个的上限。战斗中会等到战斗结束。",
  ["A button that leaves the vehicle, shown only when you can exit."] = "离开载具的按钮，仅在可以离开时显示。",
  ["A class icon on each friend row."] = "每个好友行上的职业图标。",
  ["A click on a window's header opens a Phoenix list of meter types instead of cycling through them."] = "点击窗口标题会打开 Phoenix 的计量类型列表，而不是循环切换。",
  ["A clickable button beside quests that have a usable item (placed outside combat)."] = "在有可使用物品的任务旁显示可点击按钮（在非战斗中放置）。",
  ["A cog in the title bar of every skinned window opens its Phoenix options in place."] = "每个美化窗口标题栏中的齿轮可直接打开其 Phoenix 选项。",
  ["A coloured dot for each party member targeting this enemy (shared with the party frames' enemy dots)."] = "每个以该敌人为目标的小队成员显示一个彩色圆点（与小队框体的敌人圆点共用）。",
  ["A coloured glow around player, target, focus and boss frames when you have threat."] = "你有仇恨时，玩家、目标、焦点和首领框体周围显示彩色光效。",
  ["A countdown bar under the dungeon and battleground ready pop-ups (same countdown as the minimap queue eye)."] = "地下城和战场就绪弹窗下方的倒计时条（与小地图队列之眼的倒计时相同）。",
  ["A countdown bar while you fly. The first flight on a route is timed and remembered."] = "飞行时的倒计时条。每条航线的首次飞行会被计时并记住。",
  ["A dark background behind the tracker."] = "追踪器后的深色背景。",
  ["A faint bar on your row showing your best pull on this boss."] = "你的行上显示你在该首领上最佳一次拉怪的淡色条。",
  ["A gold border around the enemy you are targeting."] = "你当前目标敌人周围的金色边框。",
  ["A green arrow on loot and rolls with a higher item level than what you wear."] = "物品等级高于当前装备的拾取和掷骰上显示绿色箭头。",
  ["A grey cross when a cast is stopped before it finishes."] = "施法在完成前停止时显示灰色叉号。",
  ["A hit on your target this soon after your cast counts as yours."] = "施法后这么短时间内对目标的命中算作你的。",
  ["A key that hides or shows every meter window. Empty means no key."] = "隐藏或显示所有计量窗口的按键。留空表示无按键。",
  ["A key that resets the meter data. Empty means no key."] = "重置计量数据的按键。留空表示无按键。",
  ["A key that switches on your \"While my layer key is active\" overrides (for example bigger nameplates or a different action bar page look). Leave empty for no key."] = "开启你的“图层按键激活时”覆盖设置的按键（例如更大的姓名板或不同的动作条页面外观）。留空表示无按键。",
  ["A light Horde or Alliance tint behind Battle.net friends in World of Warcraft."] = "在《魔兽世界》中的战网好友后显示淡淡的部落或联盟色调。",
  ["A line naming where arena frames, DR and queue status live."] = "一行说明竞技场框体、递减和队列状态的位置。",
  ["A popup grid that opens from the bin button, or a bar that is always shown along the minimap or wherever you move it."] = "从收纳按钮打开的弹出网格，或沿小地图（或你移动到的任何位置）始终显示的条。",
  ["A progress bar for experience, your watched reputation or honor. Data Bars owns this bar."] = "经验、追踪声望或荣誉的进度条。此条由数据条管理。",
  ["A red cross when a cast is interrupted."] = "施法被打断时显示红色叉号。",
  ["A red mark on enchantable slots without an enchant."] = "可附魔但未附魔的栏位上显示红色标记。",
  ["A repeat inside this time is hidden when Hide repeated lines is on."] = "开启“隐藏重复行”时，此时间内的重复会被隐藏。",
  ["A right click on the header opens a list of fights (current, overall, last saved) instead of cycling."] = "右键点击标题会打开战斗列表（当前、总计、上次保存），而不是循环切换。",
  ["A ring around your mouse cursor, so you never lose it in a busy fight."] = "鼠标指针周围的光环，让你在混乱的战斗中不会丢失指针。",
  ["A row of small buttons (Say, Party, Instance, Raid, Guild, Officer, Whisper, 1, 2) that open the chat box on that channel."] = "一排小按钮（说、小队、副本、团队、公会、官员、密语、1、2），点击即在该频道打开聊天框。",
  ["A search box in the popup that narrows the buttons by name."] = "弹窗中的搜索框，按名称筛选按钮。",
  ["A small badge with the number of new errors this session; click it to open the viewer."] = "显示本次会话新错误数量的小徽章；点击打开查看器。",
  ["A small clock for the current fight. It is the one shared timer: the Embers title bar and the Mythic+ card read the same clock."] = "当前战斗的小时钟。它是唯一共享的计时器：Embers 标题栏和史诗钥石卡片读取同一个时钟。",
  ["A small dot in the middle of the ring."] = "光环中心的小圆点。",
  ["A small frame for each enemy pet (click to target, right-click to focus)."] = "每个敌方宠物的小框体（点击设为目标，右键设为焦点）。",
  ["A small list of the next boss abilities and their times during a boss fight. Move it in Studio."] = "首领战中接下来首领技能及其时间的小列表。在 Studio 中移动。",
  ["A small mark on your focus."] = "你的焦点上的小标记。",
  ["A small popup the first time a new error happens (repeats are only counted)."] = "新错误首次发生时的小弹窗（重复只计数）。",
  ["A small read-only Phoenix panel inside Blizzard's conquest frame with your title progress and conquest."] = "暴雪征服框体中的 Phoenix 只读小面板，显示你的头衔进度和征服点数。",
  ["A soft glow around reminder icons."] = "提醒图标周围的柔和光效。",
  ["A soft shadow under Phoenix window text."] = "Phoenix 窗口文字下的柔和阴影。",
  ["A spell shown in the cooldown manager's Essential or Utility rows is hidden on your bars. Off while the cooldown manager hides icons that are on your bars (pick one)."] = "冷却管理器“核心”或“辅助”行中显示的法术会在你的动作条上隐藏。冷却管理器隐藏动作条上已有的图标时此项关闭（二选一）。",
  ["A starting look for size, spacing and icon side. Every part can still be changed on its own below."] = "大小、间距和图标位置的起始外观。下方每一项仍可单独更改。",
  ["A strip of recent casts for arena 1."] = "竞技场 1 的最近施法条。",
  ["A strip of recent casts for arena 2."] = "竞技场 2 的最近施法条。",
  ["A strip of recent casts for arena 3."] = "竞技场 3 的最近施法条。",
