  ["A thin accent border on the friends frame and an accent line under the open tab."] = "好友框体上的细强调色边框，以及打开的标签页下的强调线。",
  ["A thin accent line at the right edge shows where you are while scrolled."] = "滚动时右边缘的细强调线显示你的位置。",
