  ["A thin dark border around each icon."] = "每个图标周围的细深色边框。",
  ["A white edge when a shield is bigger than the missing health, and a red edge when a heal absorb is bigger than the current health."] = "护盾大于损失生命时显示白边，治疗吸收大于当前生命时显示红边。",
  ["A/B report"] = "A/B 报告",
  ["Abilities listed"] = "列出的技能",
