  ["Accept role checks for me"] = "替我接受职责确认",
  ["Accepts a dungeon or raid finder role check with the roles you have set. Blizzard runs this window with protected code; an addon helping here can, rarely, cause an 'interface action blocked' message. It is on by default because you chose so; turn it off if you ever see that."] = "以你设置的职责接受地下城或团队查找器的职责确认。暴雪用受保护的代码运行此窗口；插件在此协助偶尔会导致“界面行为被阻止”消息。因你的选择默认开启；如果看到该消息请关闭。",
  ["Accepts and turns in quests with at most one reward choice. Hold the pause key to read the quest."] = "接受并交付最多只有一个奖励选项的任务。按住暂停键可阅读任务。",
  ["Accepts group invites from WoW and Battle.net friends. Never while you are queued or in combat."] = "接受魔兽世界和战网好友的组队邀请。排队或战斗中从不接受。",
  ["Accepts group invites from friends, Battle.net friends and guild members. While the Friends module is on, its own per-source switches decide instead."] = "接受好友、战网好友和公会成员的组队邀请。好友模块开启时，改由其各来源开关决定。",
  ["Accepts group invites from guild members. Never while you are queued or in combat."] = "接受公会成员的组队邀请。排队或战斗中从不接受。",
