  ["Action button tooltips"] = "动作按钮鼠标提示",
  ["Action status text"] = "动作状态文字",
  ["Actions can only be dragged off with the pick-up modifier (Shift by default)."] = "只有按住拾取修饰键（默认 Shift）才能拖走动作。",
