  ["Add text slot: one line each, \"tag @ POINT x y size\" (for example health:percent @ TOPRIGHT 0 10 14)."] = "添加文字槽：每行一个，\"tag @ POINT x y size\"（例如 health:percent @ TOPRIGHT 0 10 14）。",
  ["Add your own character name to reports. Other players' names are never collected."] = "在报告中加入你自己的角色名。从不收集其他玩家的名字。",
  ["Add, remove and reorder columns. Column IDs: name, spec, damage, healing, kb, deaths, hk, rating, ratingChange, mmrBefore, mmrAfter, honor, plus any column another addon adds."] = "添加、移除和排序列。列 ID：name、spec、damage、healing、kb、deaths、hk、rating、ratingChange、mmrBefore、mmrAfter、honor，以及其他插件添加的任何列。",
  ["AddOn list"] = "插件列表",
  ["Addon compartment"] = "插件收纳栏",
  ["Addon sections in the viewer open collapsed; click a section header to expand it."] = "查看器中的插件分区默认折叠；点击分区标题展开。",
  ["Adds ID lines (spell, item, NPC, quest and 23 more kinds) to tooltips. Phoenix is the only place IDs are added."] = "在鼠标提示中添加 ID 行（法术、物品、NPC、任务及另外 23 种）。只有 Phoenix 添加 ID。",
  ["Adds Phoenix's own emoji: :smile: :grin: :laugh: :wink: :sad: :cry: :angry: :cool: :wow: :think: :sleep: :gg: :heart: :fire: :thumbsup: :dead:."] = "添加 Phoenix 自己的表情：:smile: :grin: :laugh: :wink: :sad: :cry: :angry: :cool: :wow: :think: :sleep: :gg: :heart: :fire: :thumbsup: :dead:。",
  ["Adds a Phoenix UI button above the Escape menu."] = "在 Esc 菜单上方添加 Phoenix UI 按钮。",
  ["Adds a Train all button to the class trainer."] = "在职业训练师处添加“全部训练”按钮。",
  ["Adds a glow around the frame while the class icon shows an aura."] = "职业图标显示光环时，在框体周围添加光效。",
  ["Adds channelled spells to the strip."] = "在施法条中加入引导法术。",
  ["Adds each row's share of the total when the game shows the numbers."] = "游戏显示数值时，添加每行占总量的比例。",
  ["Adds gear from your bags as commented lines, so Raidbots Top Gear can compare it."] = "将背包中的装备作为注释行加入，以便 Raidbots Top Gear 进行比较。",
  ["Adds guild name and rank to player tooltips."] = "在玩家鼠标提示中添加公会名称和会阶。",
  ["Adds kills, wipes and your best time to the tooltip of a boss you have stats for."] = "在有统计数据的首领鼠标提示中添加击杀、团灭和你的最佳时间。",
  ["Adds roles in fixed order, class-coloured counts, age, leader score and decline memory to the group tooltip."] = "在队伍鼠标提示中按固定顺序添加职责、职业着色人数、时长、队长评分和拒绝记录。",
  ["Adds the Phoenix score or item-level difference to item tooltips."] = "在物品鼠标提示中添加 Phoenix 评分或物品等级差。",
  ["Adds the enemy forces of the enemies you are fighting to the forces line."] = "将你正在战斗的敌人的敌方部队加入部队行。",
  ["Adds the highest key the player finished this season next to the score."] = "在评分旁添加该玩家本赛季完成的最高钥石。",
  ["Adds the leader's best timed key level in that dungeon next to the score."] = "在评分旁添加队长在该地下城的最佳限时钥石层数。",
  ["Adds the per-second figure to saved segments."] = "为保存的片段添加每秒数值。",
  ["Adds the player's Mythic+ score, coloured by your M+ score colour setting."] = "添加玩家的史诗钥石评分，按你的 M+ 评分颜色设置着色。",
  ["Adds the raid size to the difficulty, such as 25H."] = "在难度中加入团队规模，例如 25H。",
  ["Adds your equipped trinkets that have a use effect to the item bars."] = "将你装备的具有使用效果的饰品加入物品条。",
  ["Advanced: macro conditions that show or hide bar 1, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高级：显示或隐藏动作条 1 的宏条件，例如 [combat] show; hide。设置后将替代“显示位置”选项。",
  ["Advanced: macro conditions that show or hide bar 10, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高级：显示或隐藏动作条 10 的宏条件，例如 [combat] show; hide。设置后将替代“显示位置”选项。",
  ["Advanced: macro conditions that show or hide bar 2, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高级：显示或隐藏动作条 2 的宏条件，例如 [combat] show; hide。设置后将替代“显示位置”选项。",
  ["Advanced: macro conditions that show or hide bar 3, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高级：显示或隐藏动作条 3 的宏条件，例如 [combat] show; hide。设置后将替代“显示位置”选项。",
  ["Advanced: macro conditions that show or hide bar 4, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高级：显示或隐藏动作条 4 的宏条件，例如 [combat] show; hide。设置后将替代“显示位置”选项。",
  ["Advanced: macro conditions that show or hide bar 5, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高级：显示或隐藏动作条 5 的宏条件，例如 [combat] show; hide。设置后将替代“显示位置”选项。",
  ["Advanced: macro conditions that show or hide bar 6, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高级：显示或隐藏动作条 6 的宏条件，例如 [combat] show; hide。设置后将替代“显示位置”选项。",
  ["Advanced: macro conditions that show or hide bar 7, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高级：显示或隐藏动作条 7 的宏条件，例如 [combat] show; hide。设置后将替代“显示位置”选项。",
  ["Advanced: macro conditions that show or hide bar 8, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高级：显示或隐藏动作条 8 的宏条件，例如 [combat] show; hide。设置后将替代“显示位置”选项。",
  ["Advanced: macro conditions that show or hide bar 9, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "高级：显示或隐藏动作条 9 的宏条件，例如 [combat] show; hide。设置后将替代“显示位置”选项。",
  ["Adventure Guide"] = "冒险指南",
  ["After a boss, sends the top line through Phoenix announcements (where it goes is set on the Announcements page)."] = "首领战后，通过 Phoenix 通告发送排名第一的一行（发送位置在通告页面设置）。",
  ["After a ready check, prints who was not ready or did not answer."] = "就位确认后，列出谁未就位或未回应。",
  ["After a restore, make the Phoenix Edit Mode layout the active one."] = "恢复后，将 Phoenix 编辑模式布局设为当前布局。",
  ["After a run"] = "完成后",
  ["After a talent or specialization change, lists tracked cooldowns that are on none of your action bars."] = "天赋或专精更改后，列出不在任何动作条上的已追踪冷却。",
  ["After an enemy is seen dispelling, shows their dispel with its cooldown. Only dispels the game reports plainly are seen."] = "发现敌人驱散后，显示其驱散及冷却。只能看到游戏明确报告的驱散。",
  ["After an enemy's cast is interrupted, the plate shows \"Interrupted by <name>\" for a moment."] = "敌人施法被打断后，姓名板会短暂显示“被 <名字> 打断”。",
  ["After-match card"] = "赛后卡片",
  ["Aggro border"] = "仇恨边框",
  ["Alert again after (s)"] = "再次提醒间隔（秒）",
  ["Alert sound"] = "提醒音效",
  ["Alert toasts"] = "提醒弹窗",
  ["Alerts and toasts"] = "提醒与弹窗",
  ["All tracked quests, only those in progress, or only those ready to turn in."] = "所有追踪的任务、仅进行中的或仅可交付的。",
  ["Alphabetical, or the order you drag them into (Shift-click the bin button to edit)."] = "按字母顺序，或按你拖动的顺序（Shift 点击收纳按钮编辑）。",
  ["Also keeps errors from other addons and Blizzard's code in the viewer, on this PC only. They never join Phoenix's reports unless you allow it below."] = "同时在查看器中保留其他插件和暴雪代码的错误，仅限本机。除非你在下方允许，否则它们从不加入 Phoenix 的报告。",
  ["Also narrow Blizzard's search: minimum rating"] = "同时缩小暴雪搜索范围：最低评分",
  ["Also narrow Blizzard's search: needs my role"] = "同时缩小暴雪搜索范围：需要我的职责",
  ["Also prints the rating change in your chat window after each rated match."] = "每场评级比赛后，同时在聊天窗口输出评级变化。",
  ["Also shows a dot for each boss targeting this member."] = "同时为每个以该成员为目标的首领显示一个圆点。",
  ["Also shows the addons listed in Blizzard's addon compartment as buttons in the bin."] = "同时将暴雪插件收纳栏中的插件作为按钮显示在收纳框中。",
  ["Alt+click Phoenix UI in the minimap addon menu to show or clear the Cast History test strip."] = "在小地图插件菜单中 Alt+点击 Phoenix UI，显示或清除 Cast History 测试条。",
  ["Alt+click in the addon menu"] = "在插件菜单中 Alt+点击",
  ["Alternate power bar"] = "替代能量条",
  ["Always on the minimap"] = "始终在小地图上",
  ["Always show me"] = "始终显示我",
  ["An accent dot on communities with unread messages."] = "有未读消息的社区上显示强调色圆点。",
  ["An accent frame on transmog slots with an unsaved change."] = "有未保存更改的幻化栏位上显示强调色边框。",
  ["An accent glow on Great Vault slots you have unlocked."] = "你已解锁的宏伟宝库栏位上显示强调色光效。",
  ["An accent line under the open tab."] = "打开的标签页下显示强调线。",
  ["An accent ring on chosen talents, a dim ring on talents you can still pick."] = "已选天赋显示强调色圆环，仍可选择的天赋显示暗色圆环。",
  ["An essential or utility cooldown that is on one of your shown action bars is left out of these rows, so it appears once."] = "已在你显示的某个动作条上的核心或辅助冷却不会出现在这些行中，因此只显示一次。",
