  ["Ascent"] = "Ascent",
  ["Asks the game to show only DR categories your own spells can cause (needs DR tracking on). Your old value comes back when off."] = "请求游戏只显示你的法术能造成的递减类别（需要开启递减追踪）。关闭时恢复原值。",
  ["Asks whether to leave the group when a Dungeon Finder run is complete. Never leaves on its own."] = "地下城查找器的副本完成后询问是否离开队伍。从不自动离开。",
