  ["Dock several meter windows together under one Studio mover (Embers dock), or leave them free."] = "将多个统计窗口一起停靠在一个 Studio 移动器下（Embers 停靠），或让它们自由放置。",
  ["Docked above the group finder: your roles at a glance, with locks on roles your class cannot play."] = "停靠在队伍查找器上方：一眼看到你的职责，你的职业无法担任的职责显示锁。",
  ["Docked inside the M+ block or as its own widget (also shown in raid boss fights)."] = "停靠在史诗钥石模块中或作为独立组件（首领战中也会显示）。",
  ["Docked panel with Phoenix's sorted list of the groups your filter keeps and the why-hidden line."] = "停靠面板，显示 Phoenix 对你的筛选保留下来的队伍的排序列表，以及“为何隐藏”说明行。",
  ["Docked window gap"] = "停靠窗口间隙",
  ["Docks the Mythic+ block at the top of the Phoenix quest tracker, or shows it as its own movable window. When the Phoenix tracker is off it always uses its own window."] = "将史诗钥石模块停靠在 Phoenix 任务追踪器顶部，或作为独立可移动窗口显示。Phoenix 追踪器关闭时始终使用独立窗口。",
  ["Docks the bar on the minimap edge the bar grows along, or lets you place it with the Studio mover."] = "将此条停靠在其增长方向所沿的小地图边缘，或用 Studio 移动器自行放置。",
  ["Does not repeat the exact same announcement within 5 seconds."] = "5 秒内不重复完全相同的通告。",
  ["Double-click a group (in Blizzard's list or Phoenix's) to open its sign-up. Blizzard runs this window with protected code; an addon helping here can, rarely, cause an 'interface action blocked' message. It is on by default because you chose so; turn it off if you ever see that."] = "双击队伍（暴雪列表或 Phoenix 列表中）打开其报名。暴雪用受保护的代码运行此窗口；插件在此协助偶尔会导致“界面行为被阻止”消息。因你的选择默认开启；如果看到该消息请关闭。",
  ["Double-click a group to sign up"] = "双击队伍报名",
  ["Drag Blizzard windows (character, map, bags, talents and about 50 more) by their title. Ctrl + mouse wheel scales, Shift + right-click resets."] = "拖动暴雪窗口（角色、地图、背包、天赋及另外约 50 个）的标题移动。Ctrl + 鼠标滚轮缩放，Shift + 右键重置。",
  ["Drag a scoreboard header onto another to change the column order."] = "将记分板标题拖到另一个标题上以改变列顺序。",
  ["Drag scoreboard headers"] = "拖动记分板标题",
  ["Drag the whole selection"] = "拖动整个选择",
  ["Dragged elements snap to the Studio grid."] = "拖动的元素吸附到 Studio 网格。",
  ["Draw the pixel grid while Studio is open."] = "Studio 打开时绘制像素网格。",
  ["Draw the screen's centre lines while Studio is open."] = "Studio 打开时绘制屏幕中心线。",
  ["Draws a line from each attached element to the element it is attached to while Studio is open."] = "Studio 打开时，从每个附着元素向其附着目标绘制连线。",
