  ["Each specialization can keep its own block list for every bar (save one with /pui dbspec save). Specs without a saved set use the normal lists."] = "每个专精可以为每个动作条保留自己的屏蔽列表（用 /pui dbspec save 保存）。没有保存设置的专精使用普通列表。",
