  ["Each time you save in Edit Mode, Phoenix keeps a copy of the active layout in this profile; /pui editmode restore puts it back as a layout named Phoenix."] = "每次在编辑模式中保存时，Phoenix 都会在此配置文件中保留当前布局的副本；/pui editmode restore 会将其恢复为名为 Phoenix 的布局。",
