  ["How many matching groups the panel lists."] = "面板列出的匹配队伍数。",
  ["How many meter windows to show (up to 4). Each one has its own meter type and fight; move them in Studio. Different window sets per raid, Mythic+ or arena come from your content profiles."] = "显示的统计窗口数（最多 4 个）。每个窗口有自己的统计类型和战斗；在 Studio 中移动。团队、史诗钥石或竞技场的不同窗口组合来自你的内容配置文件。",
  ["How many names a chat report lists."] = "聊天报告列出的名字数。",
  ["How many pulls per boss the history (and the wipe trend) keeps."] = "每个首领的历史（及团灭趋势）保留的拉怪次数。",
  ["How many rated results are kept (Arena's card reads them too)."] = "保留的评级结果数（竞技场卡片也读取）。",
