  ["How many results the palette lists."] = "命令面板列出的结果数。",
  ["How many sample enemies the test mode shows."] = "测试模式显示的示例敌人数。",
  ["How many spells the breakdown lists."] = "明细列出的法术数。",
  ["How many upcoming abilities the list shows."] = "列表显示的即将到来的技能数。",
  ["How much a button darkens while on cooldown."] = "冷却时按钮变暗的程度。",
  ["How much bigger critical hits are."] = "暴击放大的程度。",
  ["How numbered channels are written in front of a line."] = "行前编号频道的书写方式。",
  ["How often out-of-range units are re-checked (seconds). Lower reacts faster and costs a little more."] = "重新检查超出范围单位的频率（秒）。越低反应越快，开销略高。",
  ["How often windows redraw in combat. 0.5 seconds is the fastest; slower saves a little CPU."] = "战斗中窗口重绘的频率。0.5 秒最快；更慢可节省少许 CPU。",
  ["How quests ready to turn in look."] = "可交付任务的外观。",
  ["How solid the row bars are."] = "行计量条的实心程度。",
  ["How solid the tooltip background is."] = "鼠标提示背景的实心程度。",
  ["How strong the border is (0 hides it, the tab line stays)."] = "边框强度（0 隐藏边框，标签线保留）。",
  ["How strong the hover highlight is."] = "悬停高亮的强度。",
