  ["Keeps the last 200 Phoenix bus signals (module enabled, profile changes, settings) for /pui trace. Off costs nothing."] = "保留最近 200 个 Phoenix 总线信号（模块启用、配置更改、设置）供 /pui trace 使用。关闭时没有任何开销。",
