  ["Mythic raids: groups 1 to 4 only"] = "史诗团队副本：仅 1 到 4 队",
  ["Mythic+ block"] = "史诗钥石模块",
  ["Mythic+ block on top"] = "史诗钥石模块置顶",
  ["Mythic+ block: timer with +2/+3 marks and pace, enemy forces, boss splits, deaths, battle res and Bloodlust, keystones and a run summary."] = "史诗钥石模块：带 +2/+3 标记和节奏的计时器、敌方部队、首领分段、死亡、战复和嗜血、钥石以及副本摘要。",
  ["Mythic+ enemy forces"] = "史诗钥石敌方部队",
  ["Mythic+ key level, arena, battleground, delve or raid when the game shows it."] = "游戏显示时的史诗钥石层数、竞技场、战场、地下堡或团队副本。",
