  ["Name the fight"] = "为战斗命名",
  ["Nameplates"] = "姓名板",
  ["Names"] = "名字",
  ["Names longer than the limit become their initials (Shadow Word: Pain -> SWP)."] = "超过上限的名字缩写为首字母（暗言术：痛 -> SWP）。",
  ["Names of the NPC colour packs to add after your own rules (your own lines always win)."] = "在你自己的规则之后添加的 NPC 颜色包名称（你自己的行总是优先）。",
  ["Names your oldest application on the panel and highlights its row."] = "在面板上指出你最早的申请并高亮其所在行。",
  ["Neutral colour"] = "中立颜色",
  ["Never collect"] = "从不收纳",
  ["Never dim these spells"] = "从不变暗这些法术",
  ["Never leave in combat"] = "战斗中从不离开",
  ["New columns are added to the left instead of the right."] = "新列添加在左侧而不是右侧。",
  ["New group sound"] = "新队伍音效",
  ["New item glow"] = "新物品光效",
  ["New items category"] = "新物品分类",
  ["New members are added above instead of below."] = "新成员添加在上方而不是下方。",
  ["New-error popup"] = "新错误弹窗",
  ["Newest icon glow"] = "最新图标光效",
  ["Next abilities list"] = "接下来的技能列表",
  ["Normal colour"] = "普通颜色",
  ["Normal text size in this area."] = "此区域的普通文字大小。",
  ["Not enough power colour"] = "能量不足颜色",
  ["Notes"] = "笔记",
