  ["Notes scale"] = "笔记缩放",
  ["Notes window"] = "笔记窗口",
  ["Notice time"] = "通知时间",
  ["Notifications: animation"] = "通知：动画",
  ["Notifications: direction"] = "通知：方向",
  ["Notifications: most lines per second"] = "通知：每秒最多行数",
  ["Notifications: on"] = "通知：开启",
  ["Notifications: opacity"] = "通知：不透明度",
  ["Notifications: scroll height"] = "通知：滚动高度",
  ["Notifications: text align"] = "通知：文字对齐",
  ["Notifications: text size"] = "通知：文字大小",
  ["Notifications: time on screen (s)"] = "通知：屏幕停留时间（秒）",
  ["Number font"] = "数字字体",
  ["Number format"] = "数字格式",
  ["Number of icons"] = "图标数量",
  ["Number style"] = "数字样式",
  ["Numbers follow FrameSort"] = "编号跟随 FrameSort",
  ["Objective progress sound"] = "目标进度音效",
  ["Objective tracker"] = "目标追踪器",
  ["Objectives go from red to green as their count fills."] = "目标随计数填满从红色变为绿色。",
  ["Off while a boss mod keeps stats"] = "首领插件记录统计时关闭",
  ["Off-tank colour"] = "副坦颜色",
  ["Off: the All filter lists only Blizzard elements you changed; the Blizzard filter always lists them all."] = "关闭：“全部”筛选只列出你更改过的暴雪元素；“暴雪”筛选始终列出全部。",
  ["On a boss, shows your best saved pull on the same boss and difficulty in the title, and after the pull how you did against it."] = "在首领战中，标题显示你在同一首领和难度上保存的最佳拉怪，拉怪后显示你与其的对比。",
  ["On: the full log goes to the dashboard, other addons' errors included, so conflicts with Phoenix can be found (same privacy filters: names and paths scrubbed). Off: only Phoenix's own errors leave this PC."] = "开启：完整日志（包括其他插件的错误）发送到仪表板，以便找出与 Phoenix 的冲突（相同的隐私过滤：名字和路径已清除）。关闭：只有 Phoenix 自己的错误离开本机。",
  ["One NPC per line: its NPC id or exact name, a colour, then optionally a size and 'glow'. Examples: 185680:B07CFF  -  Void Acolyte:B07CFF:1.1  -  Explosive:FF5468:1.2:glow. The first line for an NPC wins. In some restricted content the game hides NPC ids and names; then a rule waits until they are visible."] = "每行一个 NPC：其 NPC ID 或准确名称、颜色，然后可选大小和 'glow'。示例：185680:B07CFF  -  Void Acolyte:B07CFF:1.1  -  Explosive:FF5468:1.2:glow。同一 NPC 以第一行为准。在某些受限内容中游戏会隐藏 NPC ID 和名称；此时规则会等到它们可见。",
  ["One binding per row. Pick a modifier, a mouse button or a key, and what it does: target, menu, focus, assist, cast a spell, run a macro or use an item. Keys work while the mouse is over a frame. Each spec can keep its own list (Editing as). Changes made in combat apply as soon as combat ends."] = "每行一个绑定。选择修饰键、鼠标按键或按键，以及其作用：目标、菜单、焦点、协助、施放法术、运行宏或使用物品。鼠标在框体上时按键生效。每个专精可保留自己的列表（编辑对象）。战斗中的更改在战斗结束后立即生效。",
  ["One button per line: bar.button: options. Options: nohotkey, nomacro, nocount, hide, alpha=0.5, glow=none|pulse|solid|flash. Example: 1.12:nohotkey,alpha=0.6"] = "每行一个按钮：bar.button: options。选项：nohotkey, nomacro, nocount, hide, alpha=0.5, glow=none|pulse|solid|flash。示例：1.12:nohotkey,alpha=0.6",
  ["One colour for every glow: the theme's accent. Off keeps each glow's own colour."] = "所有光效使用一种颜色：主题强调色。关闭则保留每个光效自己的颜色。",
  ["One font everywhere"] = "全局统一字体",
  ["One large icon in the middle for a big personal or external defensive."] = "中间一个大图标，显示大型个人或外部减伤。",
  ["One line each time your pet becomes unhappy."] = "宠物每次变得不高兴时输出一行。",
  ["One line each: \"Boss name: text\". Lines starting with \"*:\" show for every boss."] = "每行一条：\"首领名: 文字\"。以 \"*:\" 开头的行对所有首领显示。",
  ["One line each: \"Original name = New text\". Blank new text hides the name."] = "每行一条：\"原名称 = 新文字\"。新文字留空则隐藏名称。",
  ["One line each: \"spellID: sound\" (a Phoenix or shared sound name), optionally \", removed\" or \", stacks\". The game plays it itself, so it works for private boss debuffs too."] = "每行一条：\"spellID: sound\"（Phoenix 或共享音效名），可选 \", removed\" 或 \", stacks\"。由游戏自己播放，因此对首领私有减益也有效。",
  ["One line per boss, by name or encounter ID: \"off\" hides Pulse bars, \"bars=4\" limits bars, \"hud=on\" or \"hud=off\" for the next-abilities list. Example: Dimensius: bars=4 hud=on"] = "每个首领一行，按名称或首领战 ID：\"off\" 隐藏 Pulse 计时条，\"bars=4\" 限制计时条数，\"hud=on\" 或 \"hud=off\" 控制接下来的技能列表。示例：Dimensius: bars=4 hud=on",
  ["One line per click: \"1: target\", \"2: focus\", \"shift-1: spell:Polymorph\", \"ctrl-3: macro:/cast [@arena1] Kick\", \"3: none\". Applied when you leave combat."] = "每次点击一行：\"1: target\"、\"2: focus\"、\"shift-1: spell:Polymorph\"、\"ctrl-3: macro:/cast [@arena1] Kick\"、\"3: none\"。脱离战斗时生效。",
  ["One line per reminder: key: sound=SoundName icon=IconID (for example 'oil: sound=Phoenix icon=463543'). Keys: intellect, stamina, lethal, pet, oil, talents, custom12345 ..."] = "每个提醒一行：key: sound=SoundName icon=IconID（例如 'oil: sound=Phoenix icon=463543'）。键：intellect, stamina, lethal, pet, oil, talents, custom12345 ...",
  ["One line per spec: spec ID = roles, e.g. '105 = HEALER, DPS'. Used when Roles per spec is 'My own list'."] = "每个专精一行：专精 ID = 职责，例如 '105 = HEALER, DPS'。在“每个专精的职责”为“我的列表”时使用。",
  ["One per line as itemID=Category (a built-in id such as consumables, or the name of one of your rules)."] = "每行一个，格式 itemID=分类（内置 ID，如 consumables，或你某条规则的名称）。",
  ["One per line: a spell ID, optionally followed by :name (for example 1234:Flask). Shows when you lack that buff."] = "每行一个：法术 ID，可选后跟 :名称（例如 1234:Flask）。缺少该增益时显示。",
  ["One search across friends, guild and recent players, with sort and actions, beside the friends list."] = "在好友列表旁，一次搜索好友、公会和最近遇到的玩家，带排序和操作。",
  ["One section per addon (collapsible, with counts, first and last seen and the session), or a single newest-first list."] = "每个插件一个分区（可折叠，带计数、首次和最近出现时间及会话），或单一的最新优先列表。",
  ["One setting for every place roles are set: manual, the role your spec plays, or your own list below. Auto stands down while BigWigs sets roles."] = "所有设置职责的地方共用一个设置：手动、你专精担任的职责或你下方的列表。BigWigs 设置职责时“自动”会让位。",
  ["One switch for every chat announcement Phoenix modules can make. Modules only pick what to say; where it goes is set here."] = "Phoenix 模块所有聊天通告的总开关。模块只决定说什么；发送到哪里在此设置。",
  ["Online friends count on the minimap; hover it for the list."] = "小地图上的在线好友数；悬停查看列表。",
  ["Online friends' names in their class colour."] = "在线好友名字使用职业颜色。",
  ["Only DR I can trigger"] = "仅我能触发的递减",
  ["Only cooldowns longer than (s)"] = "仅冷却长于（秒）",
  ["Only debuffs your class and spec can remove, or any dispellable debuff (useful to call for help)."] = "仅你的职业和专精能移除的减益，或任何可驱散减益（便于呼叫帮助）。",
  ["Only in combat"] = "仅战斗中",
  ["Only online players in the search panel."] = "搜索面板中只显示在线玩家。",
  ["Only tanks and healers get a role marker."] = "只有坦克和治疗显示职责标记。",
  ["Opacity"] = "不透明度",
  ["Opacity of a frame whose unit is out of range."] = "单位超出范围时框体的不透明度。",
  ["Opacity of bar 1 while faded."] = "动作条 1 淡出时的不透明度。",
  ["Opacity of bar 10 while faded."] = "动作条 10 淡出时的不透明度。",
  ["Opacity of bar 2 while faded."] = "动作条 2 淡出时的不透明度。",
  ["Opacity of bar 3 while faded."] = "动作条 3 淡出时的不透明度。",
  ["Opacity of bar 4 while faded."] = "动作条 4 淡出时的不透明度。",
  ["Opacity of bar 5 while faded."] = "动作条 5 淡出时的不透明度。",
  ["Opacity of bar 6 while faded."] = "动作条 6 淡出时的不透明度。",
  ["Opacity of bar 7 while faded."] = "动作条 7 淡出时的不透明度。",
  ["Opacity of bar 8 while faded."] = "动作条 8 淡出时的不透明度。",
  ["Opacity of bar 9 while faded."] = "动作条 9 淡出时的不透明度。",
  ["Opacity of out-of-range frames."] = "超出范围框体的不透明度。",
  ["Opacity of plates that are not your target while you have one; 1 keeps them fully visible."] = "你有目标时非目标姓名板的不透明度；1 保持完全可见。",
  ["Opacity of the bars."] = "计量条的不透明度。",
  ["Opacity of the chat panel."] = "聊天面板的不透明度。",
  ["Opacity of the dark background behind Phoenix bars."] = "Phoenix 计量条后深色背景的不透明度。",
  ["Opacity of the empty part of each bar."] = "每个计量条空白部分的不透明度。",
  ["Opacity of the health fill."] = "生命填充的不透明度。",
  ["Opacity of the item bar while faded."] = "物品条淡出时的不透明度。",
  ["Opacity of the pet bar while faded."] = "宠物条淡出时的不透明度。",
  ["Opacity of the stance bar while faded."] = "姿态条淡出时的不透明度。",
  ["Opacity of the text."] = "文字的不透明度。",
  ["Opacity of the vehicle exit button while faded."] = "离开载具按钮淡出时的不透明度。",
  ["Opacity of the whole tracker."] = "整个追踪器的不透明度。",
  ["Opacity out of combat"] = "非战斗不透明度",
  ["Opacity used when the where-to-show rule hides the frame (0 = invisible, higher = faded)."] = "“显示位置”规则隐藏框体时使用的不透明度（0 = 不可见，更高 = 淡化）。",
  ["Opacity used when the where-to-show rule hides the frames (0 = invisible). They stay clickable in combat because the game locks that."] = "“显示位置”规则隐藏框体时使用的不透明度（0 = 不可见）。由于游戏锁定，战斗中它们仍可点击。",
  ["Open Phoenix Studio button"] = "打开 Phoenix Studio 按钮",
  ["Open a blocked report in the copy box"] = "在复制框中打开被阻止的报告",
  ["Open containers"] = "打开容器",
  ["Open key"] = "打开按键",
  ["Open recap when I die"] = "我死亡时打开死亡回顾",
  ["Open the bin by"] = "打开收纳框的方式",
  ["Open the scoreboard after a battleground"] = "战场结束后打开记分板",
  ["Open the viewer on a new error"] = "新错误时打开查看器",
  ["Opens Phoenix's scoreboard when a battleground ends."] = "战场结束时打开 Phoenix 记分板。",
  ["Opens at"] = "打开于",
  ["Opens beside Blizzard's PvP window, or only with /pui pvp card."] = "在暴雪 PvP 窗口旁打开，或仅通过 /pui pvp card 打开。",
  ["Opens lootable bag items (caches, satchels) one at a time out of combat. Hold Shift to keep them closed."] = "非战斗时逐个打开背包中可拾取的物品（宝箱、背包）。按住 Shift 保持不打开。",
  ["Opens the error viewer by itself. Never during combat: it waits until the fight ends."] = "自动打开错误查看器。战斗中从不打开：等到战斗结束。",
  ["Opens your death recap automatically when you die."] = "你死亡时自动打开死亡回顾。",
  ["Optional: the season's achievement ID, so the count comes from the game. 0 = automatic (Gladiator) or Phoenix's count."] = "可选：赛季成就 ID，使计数来自游戏。0 = 自动（角斗士）或 Phoenix 计数。",
  ["Options mode"] = "选项模式",
  ["Oracle"] = "Oracle",
  ["Oracle search"] = "Oracle 搜索",
  ["Order of Phoenix's list, e.g. 'mprating desc, age asc'. Empty keeps Blizzard's order."] = "Phoenix 列表的排序，例如 'mprating desc, age asc'。留空保留暴雪顺序。",
  ["Order of categories, highest first. Words: cc, defensive, important. Leave one out to never show it (\"cc\" alone shows only crowd control)."] = "分类顺序，最高优先。关键词：cc, defensive, important。省略某项则从不显示（单独 \"cc\" 只显示控制）。",
  ["Order of the party frames."] = "小队框体的顺序。",
  ["Order of the search panel."] = "搜索面板的顺序。",
  ["Order raid frames by group, by role (in the role order below), by class or by name."] = "按小队、职责（按下方职责顺序）、职业或名字排序团队框体。",
  ["Order used when sorting by role (raid and party)."] = "按职责排序时使用的顺序（团队和小队）。",
  ["Other plates' opacity"] = "其他姓名板的不透明度",
  ["Other players' item level and specialization (asked from the server once, then remembered for 5 minutes; never in combat)."] = "其他玩家的物品等级和专精（向服务器询问一次，之后记住 5 分钟；战斗中从不询问）。",
