  ["Paste a Phoenix pack string (PUIPACK1|name|instance|rules). Then add its name, shown on the row, to Rule packs in use. A pack with an instance id works only inside that dungeon or raid."] = "粘贴 Phoenix 包字符串（PUIPACK1|name|instance|rules）。然后将行上显示的名称加入“使用中的规则包”。带副本 ID 的包只在该地下城或团队副本内生效。",
