  ["Pet: where to show"] = "宠物：显示位置",
  ["Pets, guardians and other summons controlled by players get a smaller plate."] = "玩家控制的宠物、守护者和其他召唤物使用较小的姓名板。",
  ["Phoenix action bars hide while a controller is active, for controller addons that bring their own bars."] = "手柄激活时隐藏 Phoenix 动作条，适用于自带动作条的手柄插件。",
  ["Phoenix action bars hide while you are inside a player house and come back when you leave."] = "你在玩家房屋内时隐藏 Phoenix 动作条，离开后恢复。",
  ["Phoenix action bars with paging, where-to-show rules, mouse-over fade, keybind mode, cooldowns, range colouring and proc glow, plus stance, pet, vehicle exit and item bars."] = "Phoenix 动作条：翻页、显示位置规则、悬停淡出、按键绑定模式、冷却、范围着色和触发光效，另有姿态条、宠物条、离开载具按钮和物品条。",
  ["Phoenix background and border on tooltips; off keeps Blizzard's look."] = "鼠标提示使用 Phoenix 背景和边框；关闭保留暴雪外观。",
  ["Phoenix bank window"] = "Phoenix 银行窗口",
  ["Phoenix bars and names use the class colours below instead of the game's."] = "Phoenix 计量条和名字使用下方的职业颜色而不是游戏的。",
  ["Phoenix bars for breath, fatigue and feign death timers."] = "Phoenix 的呼吸、疲劳和假死计时条。",
  ["Phoenix border and tabs"] = "Phoenix 边框和标签",
  ["Phoenix boxes; the check mark takes the accent colour."] = "Phoenix 复选框；勾号使用强调色。",
  ["Phoenix builds this many plates out of combat so big pulls never build frames mid-fight."] = "Phoenix 在非战斗时预先创建这么多姓名板，大规模拉怪时就不会在战斗中创建框体。",
  ["Phoenix button face on Blizzard panel buttons."] = "暴雪面板按钮使用 Phoenix 按钮外观。",
  ["Phoenix chat bubbles in the open world (Blizzard locks them inside instances)."] = "野外使用 Phoenix 聊天气泡（暴雪在副本内锁定它们）。",
  ["Phoenix draws this frame, Blizzard shows the default frame, or hidden shows neither."] = "由 Phoenix 绘制此框体、暴雪显示默认框体，或隐藏两者。",
  ["Phoenix draws your buffs and debuffs in two movable rows, or Blizzard's default buff frame stays."] = "Phoenix 在两行可移动的位置绘制你的增益和减益，或保留暴雪默认增益框体。",
  ["Phoenix dropdown boxes with an accent arrow."] = "带强调色箭头的 Phoenix 下拉框。",
  ["Phoenix ember backdrop behind mount and pet models."] = "坐骑和宠物模型后的 Phoenix 余烬背景。",
  ["Phoenix ember backdrop behind the character model."] = "角色模型后的 Phoenix 余烬背景。",
  ["Phoenix emoji art"] = "Phoenix 表情图",
  ["Phoenix error reports go to the vq8s.com dashboard through the Companion app (and the export string works). See exactly what leaves this PC with Preview on the error reporter. Nothing is shared while off."] = "Phoenix 错误报告通过 Companion 应用发送到 vq8s.com 仪表板（导出字符串也可用）。在错误报告器中使用“预览”可准确查看离开本机的内容。关闭时不共享任何内容。",
  ["Phoenix font on cinematic subtitles."] = "过场动画字幕使用 Phoenix 字体。",
  ["Phoenix fonts and bars on top-centre and minimap widgets and the encounter power bar."] = "顶部中央和小地图组件以及首领战能量条使用 Phoenix 字体和计量条。",
  ["Phoenix fonts on raid warnings, boss emotes and the red error text."] = "团队警告、首领表情和红色错误文字使用 Phoenix 字体。",
  ["Phoenix frame skin for Details! windows when that addon is installed."] = "安装 Details! 时为其窗口应用 Phoenix 框体美化。",
  ["Phoenix frame skin for Pawn when that addon is installed."] = "安装 Pawn 时为其应用 Phoenix 框体美化。",
  ["Phoenix frame skin for Plater options when that addon is installed."] = "安装 Plater 时为其选项应用 Phoenix 框体美化。",
  ["Phoenix frame skin for WeakAuras options when that addon is installed."] = "安装 WeakAuras 时为其选项应用 Phoenix 框体美化。",
  ["Phoenix input boxes with a hairline border."] = "带细线边框的 Phoenix 输入框。",
  ["Phoenix keybinds"] = "Phoenix 按键绑定",
  ["Phoenix look for Blizzard's windows, menus, tooltips and popups (their own layout and features, your theme), and Details!, Pawn, WeakAuras and Plater; each has its own switch."] = "为暴雪的窗口、菜单、鼠标提示和弹窗（保持其布局和功能，套用你的主题）以及 Details!、Pawn、WeakAuras 和 Plater 提供 Phoenix 外观；每项都有自己的开关。",
  ["Phoenix look for every context menu and dropdown list, including the damage meter's."] = "为所有右键菜单和下拉列表（包括伤害统计的）提供 Phoenix 外观。",
  ["Phoenix look on Blizzard's meter"] = "暴雪统计使用 Phoenix 外观",
  ["Phoenix look on flyouts"] = "弹出栏使用 Phoenix 外观",
  ["Phoenix minimap: shape, border, texts, coordinates, queue countdown, addon button bin and more."] = "Phoenix 小地图：形状、边框、文字、坐标、队列倒计时、插件按钮收纳框等。",
  ["Phoenix nameplates: enemy and friendly styles, threat and NPC colours, cast bars with your interrupt, aura lanes, target and focus highlights, quest, execute and Mythic+ forces indicators."] = "Phoenix 姓名板：敌方和友方样式、仇恨和 NPC 颜色、带你打断的施法条、光环通道、目标和焦点高亮、任务、斩杀和史诗钥石部队指示。",
  ["Phoenix only restyles the cooldown icons and bars; their places, sizes and which ones show stay as Blizzard's Cooldown Manager sets them (from the game's next layout pass). The safest mode for testing."] = "Phoenix 只重新美化冷却图标和计量条；它们的位置、大小和显示哪些仍由暴雪冷却管理器设定（从游戏下一次布局起）。测试时最安全的模式。",
  ["Phoenix panel"] = "Phoenix 面板",
  ["Phoenix panel on Blizzard's tutorial help tips."] = "暴雪教程帮助提示使用 Phoenix 面板。",
  ["Phoenix party and raid frames: layouts by group size, sorting, role icons, dispel highlight, aura icons, corner indicators, private auras, heal prediction, range fade and a test mode."] = "Phoenix 小队和团队框体：按队伍规模的布局、排序、职责图标、驱散高亮、光环图标、角落指示器、私有光环、治疗预测、范围淡化和测试模式。",
  ["Phoenix pet bar (hides the Blizzard one)."] = "Phoenix 宠物条（隐藏暴雪的）。",
  ["Phoenix player, target, focus, pet, target-of-target, focus-target and boss frames, and your buff and debuff rows."] = "Phoenix 玩家、目标、焦点、宠物、目标的目标、焦点目标和首领框体，以及你的增益和减益行。",
  ["Phoenix positions the game's buff bars in its own rows; off leaves them to the game."] = "Phoenix 将游戏的增益条放入自己的行中；关闭则交给游戏。",
  ["Phoenix positions the game's buff icons in its own rows; off leaves them to the game."] = "Phoenix 将游戏的增益图标放入自己的行中；关闭则交给游戏。",
  ["Phoenix positions the game's essential cooldowns in its own rows; off leaves them to the game."] = "Phoenix 将游戏的核心冷却放入自己的行中；关闭则交给游戏。",
  ["Phoenix positions the game's utility cooldowns in its own rows; off leaves them to the game."] = "Phoenix 将游戏的辅助冷却放入自己的行中；关闭则交给游戏。",
  ["Phoenix skin for the Achievements window."] = "成就窗口的 Phoenix 美化。",
  ["Phoenix skin for the AddOn list window."] = "插件列表窗口的 Phoenix 美化。",
  ["Phoenix skin for the Adventure Guide window."] = "冒险指南窗口的 Phoenix 美化。",
  ["Phoenix skin for the Archaeology window."] = "考古学窗口的 Phoenix 美化。",
