  ["Sections start collapsed"] = "分区默认折叠",
  ["Sell junk automatically"] = "自动出售垃圾",
  ["Sells grey items and items you marked as junk when you open a vendor. Off at first install; the Sell junk button works either way."] = "打开商人时出售灰色物品和你标记为垃圾的物品。首次安装时关闭；“出售垃圾”按钮总是可用。",
  ["Sells grey items when you open a vendor. While Vault is on, Vault's own junk setting decides instead."] = "打开商人时出售灰色物品。Vault 开启时，改由 Vault 自己的垃圾设置决定。",
  ["Sends each installed addon's folder name, version and whether it is enabled, so the dashboard can rank possible conflicts. Nothing else about your addons or character."] = "发送每个已安装插件的文件夹名、版本和是否启用，以便仪表板排查可能的冲突。不会发送关于你的插件或角色的其他内容。",
  ["Sends objective progress and completions through Phoenix announcements (the Quest topic there decides where)."] = "通过 Phoenix 通告发送目标进度和完成情况（由那里的“任务”主题决定发送位置）。",
  ["Sends the break through the announcement router (where it goes is set on the Announcements page; off until you turn it on there)."] = "通过通告路由发送休息（发送位置在“通告”页面设置；在那里开启前为关闭）。",
  ["Sends your key to group members who also use Phoenix, so /keys can list theirs."] = "将你的钥石发送给同样使用 Phoenix 的队友，以便 /keys 列出他们的钥石。",
  ["Sentinel notice"] = "Sentinel 通知",
  ["Separators between blocks"] = "模块之间的分隔线",
  ["Server time"] = "服务器时间",
  ["Set items (such as tier) show how many pieces of that set you are wearing."] = "套装物品（例如套装）显示你穿戴了该套装的几件。",
  ["Set pieces equipped"] = "已穿戴的套装件数",
  ["Settings"] = "设置",
  ["Settings profile used by this character. Switching applies every setting immediately."] = "此角色使用的设置配置文件。切换后立即应用所有设置。",
  ["Shade the screen edges and the centre area where your character stands, to keep frames out of the way."] = "为屏幕边缘和角色所在的中央区域加阴影，让框体避开这些区域。",
  ["Shades the end of your cast that falls inside your network latency, so you can queue the next spell there."] = "为施法末尾处于网络延迟内的部分加阴影，你可以在此时排队下一个法术。",
  ["Shadowsight timer"] = "暗影视界计时",
  ["Shaman colour"] = "萨满祭司颜色",
  ["Shape of action-button and cooldown icons: square, rounded, circle, hexagon and more (Phoenix masks)."] = "动作按钮和冷却图标的形状：方形、圆角、圆形、六边形等（Phoenix 遮罩）。",
  ["Share accepted quests"] = "共享接受的任务",
  ["Share my key with my group"] = "与队伍共享我的钥石",
  ["Share with other addons"] = "与其他插件共享",
  ["Shares quests you accept with your group when the game allows it."] = "游戏允许时与队伍共享你接受的任务。",
  ["Shift nudge step"] = "Shift 微调步长",
  ["Shift+click an icon to print the spell name and ID in chat (off so hovering never spams)."] = "Shift+点击图标在聊天中输出法术名称和 ID（关闭以免悬停刷屏）。",
  ["Shift+click prints name and ID"] = "Shift+点击输出名称和 ID",
  ["Short difficulty text inside instances, such as M+16, H, M, LFR or TW."] = "副本内的简短难度文字，例如 M+16、H、M、LFR 或 TW。",
  ["Short item cooldowns are not announced."] = "短冷却物品不通告。",
  ["Short keybind text"] = "简短按键文字",
  ["Short numbers"] = "简短数字",
  ["Shorten long ability names"] = "缩短长技能名称",
  ["Shorten names longer than"] = "缩短长于此的名字",
  ["Shortens key names so they fit: SHIFT-1 becomes S1, mouse button 4 becomes M4, mouse wheel up becomes WU."] = "缩短按键名称以便放下：SHIFT-1 变为 S1，鼠标按键 4 变为 M4，滚轮向上变为 WU。",
  ["Show"] = "显示",
  ["Show 2v2"] = "显示 2v2",
  ["Show 3v3"] = "显示 3v3",
  ["Show BG Blitz"] = "显示闪电战场",
  ["Show Edit Mode badges"] = "显示编辑模式徽章",
  ["Show IDs"] = "显示 ID",
  ["Show IDs all the time, or only while a modifier key is held."] = "始终显示 ID，或仅在按住修饰键时显示。",
  ["Show Rated BG"] = "显示评级战场",
  ["Show Solo Shuffle"] = "显示单人乱斗",
  ["Show Studio grid"] = "显示 Studio 网格",
  ["Show absorbs"] = "显示吸收",
  ["Show bar 1 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "在所有地方、从不或仅在你选择的内容、战斗状态、队伍和专精中显示动作条 1。战斗、载具、宠物对战、坐骑和驭空术即使在战斗中也立即生效。",
  ["Show bar 10 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "在所有地方、从不或仅在你选择的内容、战斗状态、队伍和专精中显示动作条 10。战斗、载具、宠物对战、坐骑和驭空术即使在战斗中也立即生效。",
