  ["Show bar 3 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "在所有地方、从不或仅在你选择的内容、战斗状态、队伍和专精中显示动作条 3。战斗、载具、宠物对战、坐骑和驭空术即使在战斗中也立即生效。",
  ["Show bar 4 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "在所有地方、从不或仅在你选择的内容、战斗状态、队伍和专精中显示动作条 4。战斗、载具、宠物对战、坐骑和驭空术即使在战斗中也立即生效。",
  ["Show bar 5 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "在所有地方、从不或仅在你选择的内容、战斗状态、队伍和专精中显示动作条 5。战斗、载具、宠物对战、坐骑和驭空术即使在战斗中也立即生效。",
  ["Show bar 6 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "在所有地方、从不或仅在你选择的内容、战斗状态、队伍和专精中显示动作条 6。战斗、载具、宠物对战、坐骑和驭空术即使在战斗中也立即生效。",
  ["Show bar 7 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "在所有地方、从不或仅在你选择的内容、战斗状态、队伍和专精中显示动作条 7。战斗、载具、宠物对战、坐骑和驭空术即使在战斗中也立即生效。",
  ["Show bar 8 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "在所有地方、从不或仅在你选择的内容、战斗状态、队伍和专精中显示动作条 8。战斗、载具、宠物对战、坐骑和驭空术即使在战斗中也立即生效。",
  ["Show bar 9 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "在所有地方、从不或仅在你选择的内容、战斗状态、队伍和专精中显示动作条 9。战斗、载具、宠物对战、坐骑和驭空术即使在战斗中也立即生效。",
  ["Show empty buttons"] = "显示空按钮",
  ["Show enemy names"] = "显示敌人名字",
  ["Show every Blizzard element under All"] = "在“全部”下显示每个暴雪元素",
  ["Show guild under friendly names"] = "友方名字下显示公会",
  ["Show in instances"] = "在副本中显示",
  ["Show incoming heals"] = "显示即将到来的治疗",
  ["Show my interrupt"] = "显示我的打断",
  ["Show names"] = "显示名字",
  ["Show only friends playing World of Warcraft: others are left out of the Phoenix list and dimmed on Blizzard's list (the game has no such filter of its own)."] = "只显示正在玩魔兽世界的好友：其他人不在 Phoenix 列表中，并在暴雪列表中变暗（游戏本身没有此过滤）。",
  ["Show or collapse each built-in category (Pinned, New, Keystone shelf, Equipment sets, Junk and the rest)."] = "显示或折叠每个内置分类（固定、新物品、钥石架、装备方案、垃圾等）。",
  ["Show or hide tooltips while you are in combat."] = "在战斗中显示或隐藏鼠标提示。",
  ["Show party frames when solo"] = "单人时显示小队框体",
  ["Show realm time instead of your computer's time."] = "显示服务器时间而不是电脑时间。",
  ["Show tenths of a second on the timer."] = "计时器显示十分之一秒。",
  ["Show the age of your oldest application"] = "显示你最早申请的时长",
  ["Show the boss frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "在所有地方、从不或仅在你选择的内容、战斗状态和队伍中显示首领框体。下面一行解释它当前为何隐藏。",
  ["Show the focus frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "在所有地方、从不或仅在你选择的内容、战斗状态和队伍中显示焦点框体。下面一行解释它当前为何隐藏。",
  ["Show the focus target frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "在所有地方、从不或仅在你选择的内容、战斗状态和队伍中显示焦点目标框体。下面一行解释它当前为何隐藏。",
  ["Show the gap to the nearest element on each side of the selected one."] = "显示所选元素各边与最近元素的间距。",
  ["Show the party frames everywhere, never, or only in the content, combat state and group you pick. The line below explains why they are hidden right now."] = "在所有地方、从不或仅在你选择的内容、战斗状态和队伍中显示小队框体。下面一行解释它们当前为何隐藏。",
  ["Show the pet frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "在所有地方、从不或仅在你选择的内容、战斗状态和队伍中显示宠物框体。下面一行解释它当前为何隐藏。",
  ["Show the player frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "在所有地方、从不或仅在你选择的内容、战斗状态和队伍中显示玩家框体。下面一行解释它当前为何隐藏。",
  ["Show the raid frames everywhere, never, or only in the content, combat state and group you pick. The line below explains why they are hidden right now."] = "在所有地方、从不或仅在你选择的内容、战斗状态和队伍中显示团队框体。下面一行解释它们当前为何隐藏。",
  ["Show the rated card"] = "显示评级卡片",
  ["Show the ring only while you are in combat."] = "仅在战斗中显示环。",
  ["Show the target frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "在所有地方、从不或仅在你选择的内容、战斗状态和队伍中显示目标框体。下面一行解释它当前为何隐藏。",
  ["Show the target of target frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "在所有地方、从不或仅在你选择的内容、战斗状态和队伍中显示目标的目标框体。下面一行解释它当前为何隐藏。",
