  ["Shows Phoenix action bar 10."] = "显示 Phoenix 动作条 10。",
  ["Shows Phoenix action bar 2 and hides the matching Blizzard bar."] = "显示 Phoenix 动作条 2 并隐藏对应的暴雪动作条。",
  ["Shows Phoenix action bar 3 and hides the matching Blizzard bar."] = "显示 Phoenix 动作条 3 并隐藏对应的暴雪动作条。",
  ["Shows Phoenix action bar 4 and hides the matching Blizzard bar."] = "显示 Phoenix 动作条 4 并隐藏对应的暴雪动作条。",
