  ["Shows Phoenix action bar 8 and hides the matching Blizzard bar."] = "显示 Phoenix 动作条 8 并隐藏对应的暴雪动作条。",
  ["Shows Phoenix action bar 9."] = "显示 Phoenix 动作条 9。",
  ["Shows Strategist progress on the card."] = "在卡片上显示战略家进度。",
  ["Shows a cast bar for this frame."] = "为此框体显示施法条。",
  ["Shows a red swipe on buttons you cannot use because you are stunned, silenced or locked out."] = "在你因昏迷、沉默或法术封锁而无法使用的按钮上显示红色遮罩。",
  ["Shows a small F at the corner of your focus target's plate."] = "在你焦点目标的姓名板角落显示小 F。",
  ["Shows an NPC's title, such as <Innkeeper> or <Flight Master>, under its name."] = "在 NPC 名字下显示其头衔，例如 <旅店老板> 或 <飞行管理员>。",
  ["Shows auras you gain in Spark."] = "在 Spark 中显示你获得的光环。",
