  ["Shows buffs on the target of target frame."] = "在目标的目标框体上显示增益。",
  ["Shows casts and channels under enemy plates, with the shield for casts you cannot interrupt."] = "在敌方姓名板下显示施法和引导，无法打断的施法带盾牌。",
  ["Shows currency in Spark."] = "在 Spark 中显示货币。",
  ["Shows damage absorbs after the health fill and heal absorbs on it."] = "在生命填充后显示伤害吸收，在其上显示治疗吸收。",
  ["Shows damage you take in Spark."] = "在 Spark 中显示你受到的伤害。",
  ["Shows damage your pet takes in Spark."] = "在 Spark 中显示宠物受到的伤害。",
  ["Shows debuffs icons on each frame."] = "在每个框体上显示减益图标。",
  ["Shows debuffs on the boss frame."] = "在首领框体上显示减益。",
  ["Shows debuffs on the focus frame."] = "在焦点框体上显示减益。",
  ["Shows debuffs on the focus target frame."] = "在焦点目标框体上显示减益。",
  ["Shows debuffs on the pet frame."] = "在宠物框体上显示减益。",
  ["Shows debuffs on the player frame."] = "在玩家框体上显示减益。",
  ["Shows debuffs on the target frame."] = "在目标框体上显示减益。",
  ["Shows debuffs on the target of target frame."] = "在目标的目标框体上显示减益。",
  ["Shows each friend's note under their name."] = "在每位好友名字下显示其备注。",
  ["Shows entering combat in Spark."] = "在 Spark 中显示进入战斗。",
  ["Shows experience in Spark."] = "在 Spark 中显示经验。",
  ["Shows heals you get in Spark."] = "在 Spark 中显示你受到的治疗。",
  ["Shows heals your pet gets in Spark."] = "在 Spark 中显示宠物受到的治疗。",
  ["Shows hits you avoid (dodge, parry, absorb...) in Spark."] = "在 Spark 中显示你避免的攻击（躲闪、招架、吸收……）。",
  ["Shows honor in Spark."] = "在 Spark 中显示荣誉。",
  ["Shows how many bosses a raid group has already killed and adds the filter word bossesdown. Uses a game function Blizzard's own list uses; it turns off by itself if a patch removes it."] = "显示团队已击杀的首领数量，并添加过滤词 bossesdown。使用暴雪自己列表所用的游戏函数；如果补丁移除它会自动关闭。",
  ["Shows how many minutes ago the group was listed."] = "显示队伍发布于多少分钟前。",
  ["Shows interrupt counts for your group (from the Embers meter data)."] = "显示你队伍的打断次数（来自 Embers 统计数据）。",
  ["Shows item or potion ready in Spark."] = "在 Spark 中显示物品或药水就绪。",
  ["Shows leaving combat in Spark."] = "在 Spark 中显示离开战斗。",
  ["Shows loot in Spark."] = "在 Spark 中显示拾取。",
  ["Shows macro names on action buttons."] = "在动作按钮上显示宏名称。",
  ["Shows money in Spark."] = "在 Spark 中显示金钱。",
  ["Shows only the button, without the decorative frame around it."] = "只显示按钮，不显示周围的装饰框。",
  ["Shows only the zone ability button, without its frame."] = "只显示区域技能按钮，不显示其框体。",
  ["Shows predicted incoming heals after the health fill."] = "在生命填充后显示预计即将到来的治疗。",
  ["Shows raid buffs someone in your group can give that you are missing."] = "显示队伍中有人能提供而你缺少的团队增益。",
  ["Shows raid target markers above plates."] = "在姓名板上方显示团队目标标记。",
  ["Shows reputation in Spark."] = "在 Spark 中显示声望。",
  ["Shows shared battle-res charges and whether you can get Bloodlust again."] = "显示共享的战复次数以及你是否能再次获得嗜血。",
  ["Shows skill ups in Spark."] = "在 Spark 中显示技能提升。",
  ["Shows the DR tray only on enemy healers."] = "仅在敌方治疗上显示递减托盘。",
  ["Shows the Phoenix UI button on the minimap edge. Left-click opens options, right-click opens Studio, Shift-click opens Sentinel, drag to move."] = "在小地图边缘显示 Phoenix UI 按钮。左键打开选项，右键打开 Studio，Shift 点击打开 Sentinel，拖动可移动。",
  ["Shows the PvP flag icon on unit frames."] = "在单位框体上显示 PvP 标记图标。",
  ["Shows the ability icon beside each bar."] = "在每个条旁显示技能图标。",
  ["Shows the achievement ID on tooltips."] = "在鼠标提示中显示成就 ID。",
  ["Shows the area poi ID on tooltips."] = "在鼠标提示中显示区域兴趣点 ID。",
  ["Shows the artifact power ID on tooltips."] = "在鼠标提示中显示神器能量 ID。",
  ["Shows the battle pet species ID on tooltips."] = "在鼠标提示中显示战斗宠物种类 ID。",
  ["Shows the bonus ID on tooltips. Off by default because it is long or rarely needed."] = "在鼠标提示中显示加成 ID。默认关闭，因为它很长且很少需要。",
  ["Shows the bound key on each action button."] = "在每个动作按钮上显示绑定按键。",
  ["Shows the buffs from your own list below when they are missing."] = "你下方列表中的增益缺失时显示。",
  ["Shows the cast bar in the resource stack."] = "在资源堆叠中显示施法条。",
  ["Shows the cast bar only on enemy healers."] = "仅在敌方治疗上显示施法条。",
  ["Shows the class resource in the resource stack."] = "在资源堆叠中显示职业资源。",
  ["Shows the crafted quality badge on items in the custom cooldown bar."] = "在自定义冷却条中的物品上显示制造品质徽章。",
  ["Shows the criteria ID on tooltips."] = "在鼠标提示中显示条件 ID。",
  ["Shows the currencies you track on the backpack."] = "在背包上显示你追踪的货币。",
  ["Shows the currency ID on tooltips."] = "在鼠标提示中显示货币 ID。",
  ["Shows the damage column on the run summary card."] = "在钥石结算卡片上显示伤害列。",
