  ["Shows the leader's realm language ([DE], [FR] ...) when an addon with LibRealmInfo is loaded."] = "加载带 LibRealmInfo 的插件时显示队长的服务器语言（[DE]、[FR]……）。",
  ["Shows the macro ID on tooltips."] = "在鼠标提示中显示宏 ID。",
