  ["Shows the quest ID on tooltips."] = "在鼠标提示中显示任务 ID。",
  ["Shows the raid markers icon on unit frames."] = "在单位框体上显示团队标记图标。",
  ["Shows the remaining time on the cast bar."] = "在施法条上显示剩余时间。",
  ["Shows the resting (player) icon on unit frames."] = "在单位框体上显示休息（玩家）图标。",
  ["Shows the seconds left on private auras."] = "在私有光环上显示剩余秒数。",
  ["Shows the seconds left on the bar."] = "在条上显示剩余秒数。",
  ["Shows the shared combat and encounter timer in the title."] = "在标题中显示共享的战斗和首领战计时。",
  ["Shows the spell ID on tooltips."] = "在鼠标提示中显示法术 ID。",
