  ["Shows the spell tooltip when you point at an icon."] = "指向图标时显示法术提示。",
  ["Shows the static (sticky) scroll area."] = "显示静态（固定）区域。",
  ["Shows the talent ID on tooltips."] = "在鼠标提示中显示天赋 ID。",
  ["Shows the time left as numbers on each cooldown icon (the game's own countdown)."] = "在每个冷却图标上以数字显示剩余时间（游戏自带倒计时）。",
  ["Shows the time left on a cooldown as numbers on the button (drawn by the game's own countdown)."] = "在按钮上以数字显示冷却剩余时间（由游戏自带倒计时绘制）。",
  ["Shows the time left on the cast bar."] = "在施法条上显示剩余时间。",
  ["Shows the time left on the invite under the Enter button. The time comes from the shared queue timer (also used by the minimap eye); set the dungeon invite length with 'Dungeon queue-pop time'."] = "在进入按钮下显示邀请剩余时间。时间来自共享的排队计时器（小地图眼睛也使用）；用“地下城排队弹出时间”设置地下城邀请时长。",
  ["Shows the time on the minimap."] = "在小地图上显示时间。",
  ["Shows the title bar with meter, fight and timer."] = "显示带统计类型、战斗和计时器的标题栏。",
  ["Shows the totem bars in the resource stack."] = "在资源堆叠中显示图腾条。",
  ["Shows the trait definition ID on tooltips. Off by default because it is long or rarely needed."] = "在鼠标提示中显示特质定义 ID。默认关闭，因为它很长且很少需要。",
  ["Shows the trait entry ID on tooltips. Off by default because it is long or rarely needed."] = "在鼠标提示中显示特质条目 ID。默认关闭，因为它很长且很少需要。",
  ["Shows the trait node ID on tooltips. Off by default because it is long or rarely needed."] = "在鼠标提示中显示特质节点 ID。默认关闭，因为它很长且很少需要。",
  ["Shows the transmog source ID on tooltips."] = "在鼠标提示中显示幻化来源 ID。",
  ["Shows the transmog visual ID on tooltips."] = "在鼠标提示中显示幻化外观 ID。",
  ["Shows the trinket only on enemy healers (needs their spec, known from the preparation phase)."] = "仅在敌方治疗上显示饰品（需要其专精，在准备阶段可知）。",
  ["Shows the unit's name on enemy plates."] = "在敌方姓名板上显示单位名字。",
