  ["Shows the zone name on the minimap."] = "在小地图上显示区域名称。",
  ["Shows whether your current role still fits the group."] = "显示你当前的职责是否仍适合队伍。",
  ["Shows whether your enemy forces are ahead of or behind an even pace for +1, +2 and +3."] = "显示你的敌方部队进度相对 +1、+2 和 +3 的均速是领先还是落后。",
  ["Shows which roles the group still needs."] = "显示队伍仍需要哪些职责。",
  ["Shows who pinged the minimap for a few seconds."] = "显示几秒钟内谁在小地图上发了信号。",
  ["Shows your /way waypoint at the top; click it to clear."] = "在顶部显示你的 /way 路径点；点击清除。",
  ["Shows your combo points, holy power, chi and similar under your target's plate. Needs the Resource Bars add-on loaded (it does not have to be switched on)."] = "在目标姓名板下显示你的连击点、神圣能量、真气等。需要加载资源条插件（不必开启）。",
  ["Shows your damage in Spark."] = "在 Spark 中显示你的伤害。",
  ["Shows your frame even when you are not in a group."] = "即使不在队伍中也显示你的框体。",
  ["Shows your heals in Spark."] = "在 Spark 中显示你的治疗。",
  ["Shows your interrupt and its cooldown beside the cast bar."] = "在施法条旁显示你的打断及其冷却。",
  ["Shows your interrupt and its cooldown next to each cast, so you see at a glance whether your kick is ready."] = "在每个施法旁显示你的打断及其冷却，一眼就能看出打断是否就绪。",
  ["Shows your misses in Spark."] = "在 Spark 中显示你的未命中。",
  ["Shows your notes for your target or the last boss, only out of combat. Move it in Studio."] = "仅在非战斗时显示你为目标或上一个首领写的笔记。在 Studio 中移动它。",
  ["Shows your own class buffs that are missing, like rogue poisons or a paladin aura."] = "显示你缺失的本职业增益，如潜行者毒药或圣骑士光环。",
  ["Shows your quest progress for an enemy, such as \"Void Acolytes slain: 3/8\", under its name."] = "在敌人名字下显示你对其的任务进度，例如“虚空侍僧已杀死：3/8”。",
