  ["Spells you want to see as small squares in a corner, one per line as CORNER:spellID, then optionally :mine or :any and a colour (RRGGBB). Example: TOPLEFT:774:mine. Use the preset button for your class's heals. In some restricted fights the game hides other players' auras; then a square stays off."] = "想在角落以小方块显示的法术，每行一个，格式为 CORNER:spellID，可选 :mine 或 :any 和颜色（RRGGBB）。示例：TOPLEFT:774:mine。用预设按钮填入你职业的治疗法术。在某些受限战斗中游戏会隐藏其他玩家的光环；此时方块保持熄灭。",
