  ["The All tab also searches your guild."] = "“全部”标签也会搜索你的公会。",
  ["The PvP trinket shows the Horde or Alliance medal."] = "PvP 饰品显示部落或联盟徽章。",
  ["The action page bar 1 shows while its paging modifier is held."] = "按住翻页修饰键时显示动作条 1 的动作页。",
  ["The action page bar 10 shows while its paging modifier is held."] = "按住翻页修饰键时显示动作条 10 的动作页。",
