  ["The action page bar 5 shows while its paging modifier is held."] = "按住翻页修饰键时显示动作条 5 的动作页。",
  ["The action page bar 6 shows while its paging modifier is held."] = "按住翻页修饰键时显示动作条 6 的动作页。",
  ["The action page bar 7 shows while its paging modifier is held."] = "按住翻页修饰键时显示动作条 7 的动作页。",
  ["The action page bar 8 shows while its paging modifier is held."] = "按住翻页修饰键时显示动作条 8 的动作页。",
  ["The action page bar 9 shows while its paging modifier is held."] = "按住翻页修饰键时显示动作条 9 的动作页。",
  ["The bar stays invisible until you point at it."] = "动作条保持不可见，直到你指向它。",
  ["The bar turns red when this many seconds are left."] = "剩余这么多秒时计量条变红。",
  ["The border and backdrop style of every plate. Each part below can still be changed on its own."] = "每个姓名板的边框和背景样式。下面每个部分仍可单独更改。",
  ["The border around every Phoenix window, frame and icon outline."] = "每个 Phoenix 窗口、框体和图标轮廓的边框。",
  ["The clock block uses 24-hour time."] = "时钟模块使用 24 小时制。",
  ["The countdown bar turns red with this many seconds left."] = "剩余这么多秒时倒计时条变红。",
  ["The docked bar fades to this while the mouse is away; 1 never fades."] = "鼠标离开时停靠条淡出到此值；1 表示从不淡出。",
  ["The dungeon ready pop-up ignores clicks for a moment so a stray click cannot accept or leave."] = "地下城就绪弹窗短时间内忽略点击，防止误点接受或离开。",
  ["The enemy's racial ability. Racials that share a cooldown with the trinket lock when the trinket is used."] = "敌人的种族技能。与饰品共享冷却的种族技能在使用饰品时锁定。",
  ["The enemy's spec icon, shown from the preparation room on."] = "敌人的专精图标，从准备室开始显示。",
  ["The enemy's trinket with its cooldown, from the game's own data."] = "敌人的饰品及其冷却，来自游戏自身数据。",
  ["The first time Phoenix bars turn on, each bar starts where your Edit Mode layout had it. Bars you already moved are kept. /pui abcapture copies them again."] = "Phoenix 动作条首次开启时，每个条从你编辑模式布局中的位置开始。已经移动过的条保持不变。/pui abcapture 会再次复制它们。",
  ["The frame around every button. Each part (border, zoom, fonts) can still be changed on its own."] = "每个按钮周围的框。每个部分（边框、缩放、字体）仍可单独更改。",
  ["The game's nameplate scale; 0 keeps the game's value."] = "游戏的姓名板缩放；0 保留游戏的值。",
  ["The game's own target plate scale; 0 keeps the game's value. Phoenix's target size above works on top of it."] = "游戏自身的目标姓名板缩放；0 保留游戏的值。上方 Phoenix 的目标大小在此基础上生效。",
  ["The header, background and border fade out and come back while your mouse is over the window; the rows stay."] = "标题、背景和边框会淡出，鼠标在窗口上时恢复；行保持显示。",
  ["The header, dropdowns and backdrop of Blizzard's meter windows fade out and come back while the mouse is over them."] = "暴雪统计窗口的标题、下拉框和背景会淡出，鼠标在其上时恢复。",
  ["The health bar under unit tooltips."] = "单位鼠标提示下的生命条。",
  ["The item bar stays faded until you point at it."] = "物品条保持淡出，直到你指向它。",
  ["The latest cast glows."] = "最近的施法发光。",
  ["The line cap for this area in big pulls."] = "大规模拉怪时此区域的行数上限。",
  ["The look of the button on the minimap that opens the bin."] = "小地图上打开收纳框的按钮外观。",
  ["The meter type and fight dropdowns in the header get the Phoenix look."] = "标题中的统计类型和战斗下拉框使用 Phoenix 外观。",
  ["The mouse wheel scrolls through everyone in the fight; there is no scroll bar."] = "鼠标滚轮滚动查看战斗中的每个人；没有滚动条。",
  ["The pet bar stays faded until you point at it."] = "宠物条保持淡出，直到你指向它。",
  ["The popup closes after the delay below once the mouse leaves it."] = "鼠标离开后，弹窗在下面的延迟后关闭。",
  ["The popup closes and the bar hides when combat starts; the bar comes back after combat."] = "战斗开始时弹窗关闭、条隐藏；脱战后条恢复。",
  ["The profile this specialization uses. No change keeps whatever profile is active."] = "此专精使用的配置文件。“不更改”保持当前激活的配置文件。",
  ["The raid layout used for every raid size when automatic picking is off."] = "关闭自动选择时所有团队规模使用的团队布局。",
  ["The same error alerts at most once in this many seconds (it is always counted)."] = "同一错误在这么多秒内最多提醒一次（总会被计数）。",
  ["The scoreboard stays open after you leave the battleground."] = "离开战场后记分板保持打开。",
  ["The shared Phoenix cast bar under each enemy, with your kick state."] = "每个敌人下方共享的 Phoenix 施法条，带你的打断状态。",
  ["The single highlight colour of Phoenix UI. Class uses your class colour."] = "Phoenix UI 的唯一强调色。“职业”使用你的职业颜色。",
  ["The spec icon shows the enemy's most important aura while it lasts (crowd control, big defensive or important, in your order)."] = "专精图标在敌人最重要的光环持续期间显示它（控制、大减伤或重要，按你的顺序）。",
  ["The spell whose range is checked. 0 uses your interrupt."] = "检查距离所用的法术。0 使用你的打断。",
  ["The stance bar stays faded until you point at it."] = "姿态条保持淡出，直到你指向它。",
  ["The strip stops moving while you point at it."] = "指向时滚动条停止移动。",
  ["The vehicle exit button stays faded until you point at it."] = "离开载具按钮保持淡出，直到你指向它。",
  ["Theme"] = "主题",
  ["Theme accent or your class colour."] = "主题强调色或你的职业颜色。",
  ["There is no combat log in Midnight: Spark works out your hits from your own casts."] = "至暗之夜中没有战斗日志：Spark 根据你自己的施法推算你的命中。",
  ["Thick or thin ring."] = "粗环或细环。",
  ["Thickness of pixel-line borders (0 hides them)."] = "像素线边框的粗细（0 隐藏）。",
  ["Thin Phoenix scroll bars in every skinned window."] = "每个美化窗口中的细 Phoenix 滚动条。",
  ["Thin accent border around each window."] = "每个窗口周围的细强调色边框。",
  ["Thin accent border around the panel."] = "面板周围的细强调色边框。",
