  ["Threat warning sound"] = "仇恨警告音效",
  ["Threat: as wanted"] = "仇恨：符合预期",
  ["Threat: changing"] = "仇恨：变化中",
  ["Threat: wrong"] = "仇恨：错误",
  ["Threshold sounds"] = "阈值音效",
  ["Tick a box to show health bars for that kind of friendly unit in that content. Unticked shows the name only (the default everywhere). Inside instances the game may keep friendly plates for itself; then its own plate shows."] = "勾选后在该内容中为该类友方单位显示生命条。未勾选只显示名字（各处默认）。副本中游戏可能自己保留友方姓名板；此时显示游戏的姓名板。",
  ["Tick a topic for the content types where it may be announced. Everything starts unticked."] = "为可通告的内容类型勾选主题。默认全部未勾选。",
  ["Tick an option for the content types where it should apply. Everything starts unticked; sound options return to your own values when they stop applying."] = "为应生效的内容类型勾选选项。默认全部未勾选；音效选项停止生效时恢复你自己的值。",
  ["Tick marks for your channels: spell ID = number of ticks, comma-separated, e.g. 15407=6, 5143=5."] = "引导法术的刻度：法术 ID = 跳数，用逗号分隔，例如 15407=6, 5143=5。",
  ["Tick marks on the timer bar where +3 and +2 run out."] = "计时条上 +3 和 +2 时间耗尽处的刻度。",
  ["Ticket status"] = "工单状态",
  ["Time format"] = "时间格式",
  ["Time in front of each line. Lines the game keeps secret in restricted content are shown unchanged."] = "每行前的时间。受限内容中游戏保密的行原样显示。",
  ["Time left on the cast bar."] = "施法条上的剩余时间。",
  ["Timer colour inside the refresh window."] = "刷新窗口内的计时器颜色。",
  ["Timer format"] = "计时器格式",
  ["Timer shows in"] = "计时器显示于",
  ["Timer text size"] = "计时器文字大小",
  ["Times Phoenix's registered entry points and Ticker jobs (/pui profile). Off costs nothing: no wrappers exist while it is off."] = "统计 Phoenix 已注册入口和 Ticker 任务的耗时（/pui profile）。关闭时无任何开销：关闭时不存在包装函数。",
  ["Timestamp colour (hex)"] = "时间戳颜色（十六进制）",
  ["Timestamps"] = "时间戳",
  ["Timestamps become links that open the line in the copy box."] = "时间戳变为链接，可在复制框中打开该行。",
  ["Tint of buttons you cannot use right now."] = "当前无法使用的按钮的色调。",
  ["Tint of buttons you lack the mana, energy or other power for."] = "缺少法力、能量或其他资源的按钮的色调。",
  ["Title bar"] = "标题栏",
  ["Toast style"] = "提示样式",
  ["Tooltip"] = "鼠标提示",
  ["Tooltip IDs"] = "鼠标提示 ID",
  ["Tooltip anchor"] = "鼠标提示锚点",
  ["Tooltip background opacity"] = "鼠标提示背景不透明度",
  ["Tooltip on hover"] = "悬停时显示提示",
  ["Tooltip position"] = "鼠标提示位置",
  ["Tooltip position, style, info lines and IDs (28 kinds, click-free copy)."] = "鼠标提示位置、样式、信息行和 ID（28 种，免点击复制）。",
  ["Tooltip scale"] = "鼠标提示缩放",
  ["Tooltips in combat"] = "战斗中的鼠标提示",
  ["Top centre container"] = "顶部中央容器",
  ["Top centre widgets"] = "顶部中央组件",
  ["Totem and pet plates show only their bar."] = "图腾和宠物姓名板只显示计量条。",
  ["Totem bars"] = "图腾条",
  ["Totem bars height"] = "图腾条高度",
  ["Totems"] = "图腾",
  ["Totems get a smaller plate so they never crowd real enemies."] = "图腾使用较小的姓名板，不会挤占真正的敌人。",
  ["Track zone quests"] = "追踪区域任务",
  ["Tracked buff bars"] = "追踪的增益条",
  ["Tracked buff icons"] = "追踪的增益图标",
  ["Tracker width."] = "追踪宽度。",
  ["Tracking, calendar and mail buttons"] = "追踪、日历和邮件按钮",
  ["Tracks quests for the zone you enter."] = "追踪你进入的区域的任务。",
  ["Trade"] = "交易",
  ["Train All button"] = "全部学习按钮",
  ["Trainer"] = "训练师",
  ["Training Grounds buttons"] = "训练场按钮",
  ["Trait trees (Delves, Skyriding)"] = "特质树（地下堡、驭空术）",
  ["Transmog"] = "幻化",
  ["Trigger list"] = "触发列表",
  ["Triggers"] = "触发",
  ["Trims the icon edges."] = "裁切图标边缘。",
  ["Trinket and racial size"] = "饰品和种族技能大小",
  ["Trinket for healers only"] = "仅治疗显示饰品",
  ["Turn off Blizzard's combat notifications"] = "关闭暴雪的战斗通知",
  ["Turn off Blizzard's incoming combat text"] = "关闭暴雪的受到战斗文字",
  ["Turn off Blizzard's outgoing combat text"] = "关闭暴雪的输出战斗文字",
  ["Turn on the client's taint log until logout so blocked actions can be traced."] = "开启客户端污染日志直到登出，以便追踪被阻止的操作。",
  ["Turns /combatlog on in the content types ticked below and off elsewhere (only a log Flow started). Raids and Mythic+ are ticked to start with."] = "在下面勾选的内容类型中开启 /combatlog，其他地方关闭（仅限 Flow 开启的日志）。团队副本和史诗钥石默认勾选。",
  ["Turns :name: codes such as :star: or :tank: into icons, with suggestions while you type."] = "将 :star: 或 :tank: 等 :name: 代码转换为图标，输入时提供建议。",
  ["Turns off the game's tutorial pop-ups; your setting comes back when this is off."] = "关闭游戏的教程弹窗；关闭此项后恢复你的设置。",
  ["Turns on the game's own enemy DR tracking (setting spellDiminishPVPEnemiesEnabled) and shows it in Phoenix's tray. Off: no DR is shown. Your old value comes back when this goes off."] = "开启游戏自带的敌方递减追踪（设置 spellDiminishPVPEnemiesEnabled）并在 Phoenix 托盘中显示。关闭：不显示递减。关闭时恢复你原来的值。",
  ["Turns the Phoenix filter for this category on or off without losing your chips."] = "开启或关闭此分类的 Phoenix 过滤，不会丢失你的标签。",
  ["Turns the game's friendly nameplates on or off for you. Your own value comes back when Phoenix nameplates turn off."] = "为你开启或关闭游戏的友方姓名板。关闭 Phoenix 姓名板后恢复你自己的值。",
  ["Type /keys to list your key, your alts' keys and your group's keys (/pui keys always works)."] = "输入 /keys 列出你的钥石、小号的钥石和队伍的钥石（/pui keys 始终可用）。",
  ["Types the confirmation word when deleting a good item."] = "删除好物品时自动输入确认词。",
  ["Typing : and a few letters shows matching emoji; click one or press Tab to insert it."] = "输入 : 和几个字母会显示匹配的表情；点击或按 Tab 插入。",
  ["Typing in the add-friend box lists matching guild members and recent players; click one to fill the box."] = "在添加好友框中输入会列出匹配的公会成员和最近玩家；点击即可填入。",
  ["UI errors"] = "界面错误",
  ["Uninterruptible colour"] = "不可打断颜色",
  ["Uninterruptible colour of plate cast bars."] = "姓名板施法条的不可打断颜色。",
  ["Unit frames"] = "单位框体",
  ["Unlocked glow"] = "解锁光效",
  ["Unread badges"] = "未读徽章",
  ["Unusable colour"] = "不可用颜色",
  ["Upgradable gear shows how many ranks are left and about how many crests they cost."] = "可升级装备显示剩余等级数以及大约需要多少纹章。",
  ["Upgrade hint"] = "升级提示",
  ["Upgrade star"] = "升级星标",
  ["Upgrade track"] = "升级轨道",
  ["Use my class colours"] = "使用我的职业颜色",
  ["Use one font in every Phoenix module, or keep each module's own font choice."] = "在所有 Phoenix 模块中使用同一字体，或保留每个模块各自的字体选择。",
  ["Use the profile you picked for raid, Mythic+, arena and other content automatically. Applies when you enter, never in combat."] = "自动使用你为团队副本、史诗钥石、竞技场和其他内容选择的配置文件。进入时应用，战斗中从不应用。",
  ["Used when Colour by debuff type is off."] = "关闭“按减益类型着色”时使用。",
  ["Used when Group health colour is Custom."] = "队伍生命颜色为“自定义”时使用。",
  ["Used when Health colour is Custom."] = "生命颜色为“自定义”时使用。",
  ["Uses the Party, Raid up to 10, Raid up to 20 or Raid up to 40 layout automatically as people join and leave. Turn off to always use one raid layout."] = "随着玩家加入和离开，自动使用小队、团队（最多 10）、团队（最多 20）或团队（最多 40）布局。关闭则始终使用一种团队布局。",
  ["Utility cooldowns"] = "辅助冷却",
  ["Utility cooldowns: Phoenix layout"] = "辅助冷却：Phoenix 布局",
  ["Utility cooldowns: growth"] = "辅助冷却：增长方向",
  ["Utility cooldowns: icon size"] = "辅助冷却：图标大小",
  ["Utility cooldowns: per row"] = "辅助冷却：每行数量",
  ["Utility cooldowns: spacing"] = "辅助冷却：间距",
  ["Vault"] = "Vault",
  ["Vehicle exit"] = "离开载具",
  ["Vehicle exit button"] = "离开载具按钮",
  ["Vehicle exit button button size"] = "离开载具按钮大小",
  ["Vehicle exit button fade opacity"] = "离开载具按钮淡出不透明度",
  ["Vehicle exit button fade until mouse-over"] = "离开载具按钮淡出直到鼠标悬停",
  ["Vehicle seats"] = "载具座位",
  ["Vertical distance from the cursor for the left/right cursor positions."] = "光标左/右位置时与光标的纵向距离。",
  ["Vertical spacing when stacked"] = "堆叠时的垂直间距",
  ["View"] = "视图",
  ["Viewer layout"] = "查看器布局",
  ["Viewer opens on"] = "查看器打开于",
  ["Viewer shows"] = "查看器显示",
  ["Voice deafen button"] = "语音静听按钮",
  ["Voice mute button"] = "语音静音按钮",
  ["Warlock colour"] = "术士颜色",
  ["Warn at (seconds left)"] = "警告时间（剩余秒数）",
  ["Warn once on many new errors"] = "大量新错误时只警告一次",
  ["Warning level for the low durability warning."] = "低耐久度警告的阈值。",
  ["Warns once when any item drops to the threshold."] = "任一物品耐久降到阈值时警告一次。",
  ["Warrior colour"] = "战士颜色",
  ["Waypoint line"] = "路径点连线",
  ["Waypoints (/way): when another addon does this"] = "路径点（/way）：当其他插件做此事时",
  ["WeakAuras options"] = "WeakAuras 选项",
  ["Weapon enchants"] = "武器附魔",
  ["Weapon oil in instances"] = "副本中的武器油",
  ["Web addresses in chat become links; click one to copy it."] = "聊天中的网址变为链接；点击可复制。",
  ["Weekly record, conquest and Great Vault"] = "每周战绩、征服点数和宏伟宝库",
  ["What /gg says."] = "/gg 说什么。",
  ["What a left click on a quest does. Right-click opens details, Ctrl-click copies a Wowhead link, Alt-click stops tracking."] = "左键点击任务时的操作。右键打开详情，Ctrl 点击复制 Wowhead 链接，Alt 点击停止追踪。",
  ["What a middle click on the minimap opens. The micro menu lists Character, Spellbook, Talents, Collections, Group Finder and more."] = "中键点击小地图打开的内容。微型菜单包括角色、法术书、天赋、收藏、队伍查找器等。",
  ["What dragged elements snap to while Snap is on: the grid, other elements' edges and centres, or both."] = "开启吸附时拖动元素吸附到：网格、其他元素的边缘和中心，或两者。",
  ["What each party member is targeting, as small frames beside the party."] = "以小框体在小队旁显示每位队员的目标。",
  ["What the DR tray attaches to. Move it further with the offsets."] = "递减托盘附着的对象。用偏移进一步移动。",
  ["What the center text zone shows."] = "中间文字区域显示的内容。",
  ["What the left text zone shows."] = "左侧文字区域显示的内容。",
  ["What the power text zone shows."] = "能量文字区域显示的内容。",
  ["What the right text zone shows."] = "右侧文字区域显示的内容。",
  ["What to announce, by content"] = "按内容决定通告什么",
  ["What window 1 shows. Threat lists your group's threat on your target. You can also left-click the window title to switch."] = "窗口 1 显示的内容。仇恨列出你队伍对你目标的仇恨。也可左键点击窗口标题切换。",
  ["What window 2 shows. Threat lists your group's threat on your target. You can also left-click the window title to switch."] = "窗口 2 显示的内容。仇恨列出你队伍对你目标的仇恨。也可左键点击窗口标题切换。",
  ["What window 3 shows. Threat lists your group's threat on your target. You can also left-click the window title to switch."] = "窗口 3 显示的内容。仇恨列出你队伍对你目标的仇恨。也可左键点击窗口标题切换。",
  ["What window 4 shows. Threat lists your group's threat on your target. You can also left-click the window title to switch."] = "窗口 4 显示的内容。仇恨列出你队伍对你目标的仇恨。也可左键点击窗口标题切换。",
  ["What you see when a key finishes: a summary card with time, score change and everyone's numbers, a chat line, or nothing."] = "钥石完成时你看到的：带时间、分数变化和每个人数据的汇总卡片、一行聊天，或什么都没有。",
  ["When !KalielsTracker, KalielsTracker is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "加载 !KalielsTracker, KalielsTracker 时，选择由 Phoenix 还是该插件负责此功能。Phoenix 负责：另一个插件从下次加载起被禁用。另一个插件负责：此 Phoenix 模块保持关闭。",
  ["When AutoQueue is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "加载 AutoQueue 时，选择 Phoenix 是否也执行此功能。两个插件都不会被禁用。",
  ["When Baganator, Bagnon, AdiBags, ArkInventory, BetterBags, Combuctor, LiteBag is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "加载 Baganator, Bagnon, AdiBags, ArkInventory, BetterBags, Combuctor, LiteBag 时，选择由 Phoenix 还是该插件负责此功能。Phoenix 负责：另一个插件从下次加载起被禁用。另一个插件负责：此 Phoenix 模块保持关闭。",
  ["When Bartender4, Dominos, ElvUI, EllesmereUIActionBars, ConsolePort_Bar, LUI is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "加载 Bartender4, Dominos, ElvUI, EllesmereUIActionBars, ConsolePort_Bar, LUI 时，选择由 Phoenix 还是该插件负责此功能。Phoenix 负责：另一个插件从下次加载起被禁用。另一个插件负责：此 Phoenix 模块保持关闭。",
  ["When BigWigs is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "加载 BigWigs 时，选择 Phoenix 是否也执行此功能。两个插件都不会被禁用。",
  ["When BigWigs, DBM-Core is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "加载 BigWigs, DBM-Core 时，选择 Phoenix 是否也执行此功能。两个插件都不会被禁用。",
  ["When BugSack is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "加载 BugSack 时，选择 Phoenix 是否也执行此功能。两个插件都不会被禁用。",
  ["When Details, Skada, Recount is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "加载 Details, Skada, Recount 时，选择由 Phoenix 还是该插件负责此功能。Phoenix 负责：另一个插件从下次加载起被禁用。另一个插件负责：此 Phoenix 模块保持关闭。",
  ["When EllesmereUICooldownManager, BetterCooldownManager, CooldownManagerCentered is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "加载 EllesmereUICooldownManager, BetterCooldownManager, CooldownManagerCentered 时，选择由 Phoenix 还是该插件负责此功能。Phoenix 负责：另一个插件从下次加载起被禁用。另一个插件负责：此 Phoenix 模块保持关闭。",
  ["When EllesmereUIResourceBars, SenseiClassResourceBar, PersonalResourceReskin is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "加载 EllesmereUIResourceBars, SenseiClassResourceBar, PersonalResourceReskin 时，选择由 Phoenix 还是该插件负责此功能。Phoenix 负责：另一个插件从下次加载起被禁用。另一个插件负责：此 Phoenix 模块保持关闭。",
  ["When MikScrollingBattleText, Parrot, xCT+ is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "加载 MikScrollingBattleText, Parrot, xCT+ 时，选择由 Phoenix 还是该插件负责此功能。Phoenix 负责：另一个插件从下次加载起被禁用。另一个插件负责：此 Phoenix 模块保持关闭。",
  ["When MythicDungeonTools is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "加载 MythicDungeonTools 时，选择 Phoenix 是否也执行此功能。两个插件都不会被禁用。",
  ["When Prat-3.0, Chattynator, Chatter, Glass, WIM, BasicChatMods is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "加载 Prat-3.0, Chattynator, Chatter, Glass, WIM, BasicChatMods 时，选择由 Phoenix 还是该插件负责此功能。Phoenix 负责：另一个插件从下次加载起被禁用。另一个插件负责：此 Phoenix 模块保持关闭。",
  ["When PremadeGroupsFilter is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "加载 PremadeGroupsFilter 时，选择由 Phoenix 还是该插件负责此功能。Phoenix 负责：另一个插件从下次加载起被禁用。另一个插件负责：此 Phoenix 模块保持关闭。",
  ["When Questie is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "加载 Questie 时，选择 Phoenix 是否也执行此功能。两个插件都不会被禁用。",
  ["When Studio shows each mover's name."] = "Studio 何时显示每个移动器的名称。",
  ["When TomTom is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "加载 TomTom 时，选择 Phoenix 是否也执行此功能。两个插件都不会被禁用。",
  ["When Unit Frames attaches these bars under your player frame, they take its width. Off keeps the width set here."] = "单位框体将这些条附加在玩家框体下方时，它们采用其宽度。关闭则保持此处设置的宽度。",
  ["When WarpDeplete, MythicPlusTimer, AngryKeystones is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "加载 WarpDeplete, MythicPlusTimer, AngryKeystones 时，选择由 Phoenix 还是该插件负责此功能。Phoenix 负责：另一个插件从下次加载起被禁用。另一个插件负责：此 Phoenix 模块保持关闭。",
  ["When a battleground ends, a countdown leaves for you. Cancel it or leave at once. Arenas are never left for you."] = "战场结束时，会开始自动离开倒计时。可取消或立即离开。竞技场从不自动离开。",
  ["When a cast fails because the target is out of line of sight, its plate flashes with an 'Out of sight' tag (the game has no live line-of-sight check for addons)."] = "施法因目标不在视野中而失败时，其姓名板闪烁并显示“视野外”标签（游戏没有为插件提供实时视野检查）。",
  ["When a dungeon, raid or battleground invite pops, a countdown shows by the queue eye. Group Finder owns the timer; the minimap only shows it."] = "地下城、团队副本或战场邀请弹出时，队列眼睛旁显示倒计时。计时器归队伍查找器所有；小地图只显示它。",
  ["When a tracked cooldown glows."] = "追踪的冷却何时发光。",
  ["When an NPC colour meets threat"] = "NPC 颜色与仇恨冲突时",
  ["When an invite pops, a large Enter button appears. Phoenix never presses it for you."] = "邀请弹出时出现一个大的进入按钮。Phoenix 从不替你点击。",
  ["When another player sends you a report, you get a prompt first (or it is refused)."] = "其他玩家向你发送报告时，会先提示你（或拒绝）。",
  ["When cast history strips are shown."] = "何时显示施法历史条。",
  ["When casts come faster than the strip moves, it speeds up this much."] = "施法速度快于滚动条移动时，滚动条加速这么多。",
  ["When sArena, sArena_Reloaded, sArenaReloaded, Gladius, GladiusEx is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "加载 sArena, sArena_Reloaded, sArenaReloaded, Gladius, GladiusEx 时，选择由 Phoenix 还是该插件负责此功能。Phoenix 负责：另一个插件从下次加载起被禁用。另一个插件负责：此 Phoenix 模块保持关闭。",
  ["When someone types !keys in party chat, your key is posted through Phoenix announcements (Keystones topic decides where)."] = "有人在小队聊天中输入 !keys 时，通过 Phoenix 通告发布你的钥石（由“钥石”主题决定位置）。",
  ["When the combat timer is shown."] = "何时显示战斗计时器。",
  ["When the global cooldown bar is drawn."] = "何时绘制公共冷却条。",
  ["When the language uses letters the game font lacks (Arabic, or Russian and Chinese on another client), Phoenix text uses a matching font from the media pack."] = "当语言使用游戏字体缺少的字符时（阿拉伯语，或在其他客户端上的俄语和中文），Phoenix 文字使用媒体包中匹配的字体。",
  ["When the warning sound plays."] = "何时播放警告音效。",
  ["When too many lines come at once, the extra ones are counted and shown as one \"+N more\" line."] = "一次来的行太多时，多余的会被计数并显示为一行“+N 条更多”。",
  ["When tooltips are hidden in combat, holding this key shows them anyway."] = "战斗中隐藏鼠标提示时，按住此键仍会显示。",
  ["When you are below the last visible row, your own row replaces it with your real rank."] = "当你位于最后一个可见行之下时，你自己的行以真实排名替换它。",
  ["When your group is ready or a Group Finder group invites you, the game icon flashes, a sound plays and a notice appears."] = "当你的队伍就绪或队伍查找器中的队伍邀请你时，游戏图标闪烁、播放音效并出现通知。",
  ["Where Mythic+ score colours come from in tooltips, Group Finder and data bars."] = "鼠标提示、队伍查找器和数据条中史诗钥石分数颜色的来源。",
  ["Where announcements go. Only me prints a local line nobody else sees; Group picks party, raid or instance for you."] = "通告发送的位置。“仅自己”输出一行别人看不到的本地文字；“队伍”自动选择小队、团队或副本频道。",
  ["Where auto combat logging turns the log on. Works alongside recorder addons: a log they started is never stopped."] = "自动战斗日志在哪里开启日志。可与记录插件同时使用：它们开启的日志从不会被停止。",
  ["Where each online friend is."] = "每位在线好友的位置。",
  ["Where each pet frame sits."] = "每个宠物框体的位置。",
  ["Where on the frame the private auras sit."] = "私有光环在框体上的位置。",
  ["Where text lines up in the area."] = "文字在区域中的对齐方式。",
  ["Where the M+ block sits"] = "史诗钥石模块的位置",
  ["Where the Phoenix panel sits next to the group finder."] = "Phoenix 面板在队伍查找器旁的位置。",
  ["Where the channel bar sits next to chat window 1."] = "频道条在聊天窗口 1 旁的位置。",
  ["Where the clock sits on the minimap."] = "时钟在小地图上的位置。",
  ["Where the coordinates sit."] = "坐标的位置。",
  ["Where the detached panel sits."] = "分离面板的位置。",
  ["Where the difficulty text sits."] = "难度文字的位置。",
  ["Where the dispel icons sit."] = "驱散图标的位置。",
  ["Where the elite / rare icon sits on enemy plates. You can also drag it in the preview."] = "精英/稀有图标在敌方姓名板上的位置。也可在预览中拖动。",
  ["Where the game blocks addon chat (Mythic+, PvP, boss fights), a report waits and posts when the key, match or boss ends. Say and Yell ask you first."] = "游戏阻止插件聊天的地方（史诗钥石、PvP、首领战），报告会等待，在钥石、比赛或首领战结束时发布。说和大喊会先询问你。",
  ["Where the game's DR data is drawn. Needs DR tracking on."] = "游戏递减数据的绘制位置。需要开启递减追踪。",
  ["Where the health text sits on enemy plates. You can also drag it in the preview."] = "生命值文字在敌方姓名板上的位置。也可在预览中拖动。",
  ["Where the health text sits."] = "生命值文字的位置。",
  ["Where the m+ forces sits on enemy plates. You can also drag it in the preview."] = "史诗钥石部队在敌方姓名板上的位置。也可在预览中拖动。",
  ["Where the name sits on enemy plates. You can also drag it in the preview."] = "名字在敌方姓名板上的位置。也可在预览中拖动。",
  ["Where the name sits on the frame."] = "名字在框体上的位置。",
  ["Where the name sits on the health bar."] = "名字在生命条上的位置。",
  ["Where the power bar sits."] = "能量条的位置。",
  ["Where the quest icon sits on enemy plates. You can also drag it in the preview."] = "任务图标在敌方姓名板上的位置。也可在预览中拖动。",
  ["Where the raid marker sits on enemy plates. You can also drag it in the preview."] = "团队标记在敌方姓名板上的位置。也可在预览中拖动。",
  ["Where the search panel sits."] = "搜索面板的位置。",
  ["Where the window opens on screen. Dragging the window updates this."] = "窗口在屏幕上打开的位置。拖动窗口会更新此项。",
  ["Where the zone name sits on the minimap."] = "区域名称在小地图上的位置。",
  ["Where to remind"] = "在哪里提醒",
  ["Where to show"] = "在哪里显示",
  ["Where to switch"] = "在哪里切换",
  ["Which action page (12 slots) bar 10 shows."] = "动作条 10 显示哪个动作页（12 个栏位）。",
  ["Which action page (12 slots) bar 2 shows."] = "动作条 2 显示哪个动作页（12 个栏位）。",
  ["Which action page (12 slots) bar 3 shows."] = "动作条 3 显示哪个动作页（12 个栏位）。",
  ["Which action page (12 slots) bar 4 shows."] = "动作条 4 显示哪个动作页（12 个栏位）。",
  ["Which action page (12 slots) bar 5 shows."] = "动作条 5 显示哪个动作页（12 个栏位）。",
  ["Which action page (12 slots) bar 6 shows."] = "动作条 6 显示哪个动作页（12 个栏位）。",
  ["Which action page (12 slots) bar 7 shows."] = "动作条 7 显示哪个动作页（12 个栏位）。",
  ["Which action page (12 slots) bar 8 shows."] = "动作条 8 显示哪个动作页（12 个栏位）。",
  ["Which action page (12 slots) bar 9 shows."] = "动作条 9 显示哪个动作页（12 个栏位）。",
  ["Which auras are shown."] = "显示哪些光环。",
  ["Which auras this lane shows."] = "此通道显示哪些光环。",
  ["Which battlegrounds use the countdown."] = "哪些战场使用倒计时。",
  ["Which buffs are shown."] = "显示哪些增益。",
  ["Which colour a listed NPC gets in combat."] = "列表中的 NPC 在战斗中使用哪种颜色。",
  ["Which corner of the conquest frame the panel sits in."] = "面板位于征服框体的哪个角落。",
  ["Which debuffs are shown."] = "显示哪些减益。",
  ["Which errors the viewer lists first."] = "查看器优先列出哪些错误。",
  ["Which minimap corner the Phoenix buttons start from."] = "Phoenix 按钮从小地图哪个角开始。",
  ["Which of your runs boss splits are compared with."] = "首领分段与你的哪次记录对比。",
  ["Which scroll area shows it."] = "由哪个滚动区域显示。",
  ["Which session the viewer shows first."] = "查看器首先显示哪个会话。",
  ["Which side of the bar the icon sits on."] = "图标位于计量条的哪一侧。",
  ["Which side of the cast bar the icon sits on."] = "图标位于施法条的哪一侧。",
  ["Which side of the frame the portrait sits on."] = "头像位于框体的哪一侧。",
  ["Which side the spec icon sits on."] = "专精图标位于哪一侧。",
  ["Which sound plays: four game sounds, then every sound in the media library (yours and other addons' shared sounds)."] = "播放哪个音效：四个游戏音效，然后是媒体库中的所有音效（你的以及其他插件共享的音效）。",
  ["Which tiers the pace line compares against."] = "节奏线与哪些层级比较。",
  ["Which way boss frames 2 to 5 are added."] = "首领框体 2 到 5 的添加方向。",
  ["Which way buttons fill a line; the popup opens and the bar docks on that side."] = "按钮填充一行的方向；弹窗在该侧打开，条也停靠在该侧。",
  ["Which way extra rows are added."] = "额外行的添加方向。",
  ["Which way extra rows of bar 1 are added."] = "动作条 1 额外行的添加方向。",
  ["Which way extra rows of bar 10 are added."] = "动作条 10 额外行的添加方向。",
  ["Which way extra rows of bar 2 are added."] = "动作条 2 额外行的添加方向。",
  ["Which way extra rows of bar 3 are added."] = "动作条 3 额外行的添加方向。",
  ["Which way extra rows of bar 4 are added."] = "动作条 4 额外行的添加方向。",
  ["Which way extra rows of bar 5 are added."] = "动作条 5 额外行的添加方向。",
  ["Which way extra rows of bar 6 are added."] = "动作条 6 额外行的添加方向。",
  ["Which way extra rows of bar 7 are added."] = "动作条 7 额外行的添加方向。",
  ["Which way extra rows of bar 8 are added."] = "动作条 8 额外行的添加方向。",
  ["Which way extra rows of bar 9 are added."] = "动作条 9 额外行的添加方向。",
  ["Which way lines scroll."] = "行滚动的方向。",
  ["Which way new icons are added on a row."] = "新图标在一行中的添加方向。",
  ["Which way older casts move."] = "旧施法移动的方向。",
  ["Which way the buttons of bar 1 run."] = "动作条 1 按钮的排列方向。",
  ["Which way the buttons of bar 10 run."] = "动作条 10 按钮的排列方向。",
  ["Which way the buttons of bar 2 run."] = "动作条 2 按钮的排列方向。",
  ["Which way the buttons of bar 3 run."] = "动作条 3 按钮的排列方向。",
  ["Which way the buttons of bar 4 run."] = "动作条 4 按钮的排列方向。",
  ["Which way the buttons of bar 5 run."] = "动作条 5 按钮的排列方向。",
  ["Which way the buttons of bar 6 run."] = "动作条 6 按钮的排列方向。",
  ["Which way the buttons of bar 7 run."] = "动作条 7 按钮的排列方向。",
  ["Which way the buttons of bar 8 run."] = "动作条 8 按钮的排列方向。",
  ["Which way the buttons of bar 9 run."] = "动作条 9 按钮的排列方向。",
  ["While Pulse shows boss bars, sets the game's own timeline to its empty view. Your previous view comes back when you turn this off."] = "Pulse 显示首领条时，将游戏自带时间轴设为空视图。关闭此项时恢复你之前的视图。",
  ["While Spark is on, the game's combat state, reactive, honor and reputation popups are off. Restored when this or Spark is off."] = "Spark 开启时，关闭游戏的战斗状态、反应、荣誉和声望弹出提示。此项或 Spark 关闭时恢复。",
  ["While Spark is on, the game's own damage and healing numbers over enemies are off. Your old setting comes back when this or Spark is off."] = "Spark 开启时，关闭游戏在敌人头上显示的伤害和治疗数字。此项或 Spark 关闭时恢复你原来的设置。",
  ["While Spark is on, the game's own text over your character is off. Restored when this or Spark is off."] = "Spark 开启时，关闭游戏在你角色头上显示的文字。此项或 Spark 关闭时恢复。",
  ["While a key runs, Ascent's Mythic+ block sits at the top of the tracker (Ascent owns the timer)."] = "钥石进行时，Ascent 的史诗钥石模块位于追踪顶部（计时器由 Ascent 负责）。",
  ["While a report waits, it also opens in the copy box so you can paste it yourself."] = "报告等待发送时，也会在复制框中打开，方便你自己粘贴。",
  ["While a tooltip shows IDs, this key opens them in the copy box. It is only taken while IDs are on screen, and never over a key you bound yourself. Empty turns it off."] = "鼠标提示显示 ID 时，此键在复制框中打开它们。仅在 ID 显示于屏幕时占用，且不会覆盖你自己绑定的按键。留空则关闭。",
  ["While an achievement ID setting is 0, Phoenix looks up the season's title achievement in the game's list (once per season) and reads its progress."] = "成就 ID 设置为 0 时，Phoenix 在游戏列表中查找本赛季的头衔成就（每赛季一次）并读取其进度。",
  ["While the developer profiler has samples, each module page shows how much time that module took."] = "开发者性能分析器有采样时，每个模块页面会显示该模块耗时。",
  ["While you fish: a bar with the time left on the cast and a catch counter for this session. Off by default."] = "钓鱼时：显示施放剩余时间的条和本次会话的钓获计数。默认关闭。",
  ["Whisper sound"] = "密语音效",
  ["Whisper tab width"] = "密语标签宽度",
  ["Whisper window width"] = "密语窗口宽度",
  ["Who shows coordinates"] = "由谁显示坐标",
  ["Who the player is targeting."] = "该玩家的目标。",
  ["Whose auras the sounds watch: you (boss debuffs on you), your target or your focus."] = "音效监视谁的光环：你（你身上的首领减益）、你的目标或你的焦点。",
  ["Widget power bar"] = "组件能量条",
  ["Widgets and alt power"] = "组件和替代能量",
  ["Widgets below the minimap"] = "小地图下方的组件",
  ["Width"] = "宽度",
  ["Width and height of the minimap."] = "小地图的宽度和高度。",
  ["Width of each docked Blizzard meter window."] = "每个停靠的暴雪统计窗口的宽度。",
