  ["Width of the Mythic+ block."] = "史诗钥石模块的宽度。",
  ["Width of the bar; blocks share it equally."] = "条的宽度；各模块平分。",
  ["Width of the boss frame in pixels."] = "首领框体宽度（像素）。",
  ["Width of the cast bar; 0 matches the frame."] = "施法条宽度；0 与框体一致。",
  ["Width of the cursor ring."] = "光标环的宽度。",
  ["Width of the focus frame in pixels."] = "焦点框体宽度（像素）。",
  ["Width of the focus target frame in pixels."] = "焦点目标框体宽度（像素）。",
  ["Width of the personal resource bar stack."] = "个人资源条堆叠的宽度。",
  ["Width of the pet frame in pixels."] = "宠物框体宽度（像素）。",
  ["Width of the player frame in pixels."] = "玩家框体宽度（像素）。",
  ["Width of the progress bar."] = "进度条的宽度。",
  ["Width of the target frame in pixels."] = "目标框体宽度（像素）。",
  ["Width of the target of target frame in pixels."] = "目标的目标框体宽度（像素）。",
