  ["Window 4: shows"] = "窗口 4：显示",
  ["Window animations"] = "窗口动画",
  ["Window background opacity."] = "窗口背景不透明度。",
  ["Window border"] = "窗口边框",
  ["Window drag strip height"] = "窗口拖动条高度",
  ["Window gear button"] = "窗口齿轮按钮",
  ["Window layout"] = "窗口布局",
  ["Window panels"] = "窗口面板",
  ["Window scale"] = "窗口缩放",
  ["Window snapping"] = "窗口吸附",
  ["Window text outline"] = "窗口文字描边",
  ["Window tint"] = "窗口色调",
  ["Window width"] = "窗口宽度",
  ["Windows 2-4 dock to the previous one, so moving window 1 moves the set."] = "窗口 2-4 停靠到前一个窗口，移动窗口 1 会移动整组。",
  ["Windows open where you last left them. Off: they move only until closed."] = "窗口在你上次离开的位置打开。关闭：仅在关闭前保持移动位置。",
  ["Wins needed when Phoenix counts them itself."] = "Phoenix 自行计数时所需的胜场。",
  ["Wins toward each title. Uses the game's own achievement count when the season has one; otherwise Phoenix counts wins taken at or above the title rating."] = "每个头衔的胜场。如果本赛季有游戏成就计数则使用它；否则 Phoenix 统计在头衔评级或以上取得的胜场。",
  ["Wisdom"] = "智慧",
  ["With BigWigs loaded, adds a \"Phoenix UI\" bar style you can pick in BigWigs' bar options."] = "加载 BigWigs 时，添加可在 BigWigs 计时条选项中选择的“Phoenix UI”样式。",
  ["With FrameSort loaded, the arena numbers follow its sorted enemy order (matching its EnemyFrame macros)."] = "加载 FrameSort 时，竞技场编号遵循其排序的敌人顺序（与其 EnemyFrame 宏一致）。",
  ["With In game only, also leave out friends playing a different version of World of Warcraft."] = "选择“仅游戏中”时，也排除正在玩其他版本魔兽世界的好友。",
  ["With Masque loaded, cast icons use the skin you pick for \"Phoenix UI: Cast History\" in Masque."] = "加载 Masque 时，施法图标使用你在 Masque 中为“Phoenix UI: Cast History”选择的皮肤。",
  ["With Raider.IO loaded, adds the leader's Raider.IO score to each row (filter words rio and riomain work either way)."] = "加载 Raider.IO 时，为每行添加队长的 Raider.IO 分数（过滤词 rio 和 riomain 无论如何都可用）。",
  ["With several elements selected, dragging one moves them all."] = "选中多个元素时，拖动其中一个会移动全部。",
  ["Words for the dungeons, raids or delves to keep (see the word list in the help panel; the season's words are added live). Empty keeps all."] = "要保留的地下城、团队副本或地下堡的词（见帮助面板中的词表；本赛季的词实时添加）。留空则全部保留。",
  ["Words never hidden in paths"] = "路径中永不隐藏的词",
  ["World label colour"] = "世界标签颜色",
  ["World loot list"] = "世界拾取列表",
  ["World markers"] = "世界标记",
  ["World: Achievement ID"] = "世界：成就 ID",
  ["World: Area POI ID"] = "世界：区域兴趣点 ID",
  ["World: Criteria ID"] = "世界：条件 ID",
  ["World: Currency ID"] = "世界：货币 ID",
  ["World: NPC ID"] = "世界：NPC ID",
  ["World: Object ID"] = "世界：物体 ID",
  ["World: Quest ID"] = "世界：任务 ID",
  ["World: Vignette ID"] = "世界：稀有标记 ID",
  ["Write every readable number in thousands, millions or billions."] = "将每个可读数字写成千、百万或十亿。",
  ["Writes 1, 2, 3 beside each frame (matches /target arena1)."] = "在每个框体旁写 1、2、3（与 /target arena1 对应）。",
  ["Writes 1., 2., 3. before names."] = "在名字前写 1.、2.、3.。",
  ["Writes 1/2, 1/4 or immune when the game's values are readable (hidden values show icon and swipe only)."] = "游戏数值可读时写 1/2、1/4 或免疫（隐藏数值只显示图标和遮罩）。",
  ["Writes Blizzard's own server-side minimum rating filter. Your previous Blizzard filter is saved and put back when this returns to 0."] = "写入暴雪自己的服务器端最低评级过滤。你之前的暴雪过滤会被保存，并在此项归 0 时恢复。",
  ["Writes W or L for each round once the game shows the round count plainly (it is hidden during play)."] = "游戏明确显示回合数后，为每回合写 W 或 L（比赛中隐藏）。",
  ["Writes the boss name (or Combat) before the time."] = "在时间前写首领名字（或“战斗”）。",
  ["Writes the buff name under each icon."] = "在每个图标下写增益名称。",
  ["Writes the item level on equippable items."] = "在可装备物品上写物品等级。",
  ["Writes the pet's name on its bar (the game may hide some)."] = "在宠物的条上写其名字（游戏可能隐藏部分）。",
  ["Writes the quest level before the title."] = "在标题前写任务等级。",
  ["XP / reputation / honor bar"] = "经验/声望/荣誉条",
  ["XP / reputation bar"] = "经验/声望条",
  ["Yellow below (seconds)"] = "低于此值变黄（秒）",
  ["You and each party member get your own frame that you can move anywhere in Studio, instead of one row. Sorting by role does not apply while this is on."] = "你和每位队员都有自己的框体，可在 Studio 中移动到任意位置，而不是一行。开启时按职责排序不生效。",
  ["Your character name is replaced by [player] as a whole word, and GUIDs keep only their kind, before anything is shared or uploaded."] = "在共享或上传任何内容前，你的角色名会作为完整单词替换为 [player]，GUID 只保留其类型。",
