  ["Order of the buttons on auto item bar 5."] = "自动物品条 5 上按钮的顺序。",
  ["Show auto item bar 1 everywhere, never, or only in the content, combat state, group and specialization you pick."] = "在任何地方、从不，或仅在你选择的内容、战斗状态、队伍和专精中显示自动物品条 1。",
  ["Show auto item bar 2 everywhere, never, or only in the content, combat state, group and specialization you pick."] = "在任何地方、从不，或仅在你选择的内容、战斗状态、队伍和专精中显示自动物品条 2。",
  ["Show auto item bar 3 everywhere, never, or only in the content, combat state, group and specialization you pick."] = "在任何地方、从不，或仅在你选择的内容、战斗状态、队伍和专精中显示自动物品条 3。",
  ["Show auto item bar 4 everywhere, never, or only in the content, combat state, group and specialization you pick."] = "在任何地方、从不，或仅在你选择的内容、战斗状态、队伍和专精中显示自动物品条 4。",
  ["Show auto item bar 5 everywhere, never, or only in the content, combat state, group and specialization you pick."] = "在任何地方、从不，或仅在你选择的内容、战斗状态、队伍和专精中显示自动物品条 5。",
  ["Shows cooldown swipes on auto item bar 1."] = "在自动物品条 1 上显示冷却转圈。",
  ["Shows cooldown swipes on auto item bar 2."] = "在自动物品条 2 上显示冷却转圈。",
  ["Shows cooldown swipes on auto item bar 3."] = "在自动物品条 3 上显示冷却转圈。",
  ["Shows cooldown swipes on auto item bar 4."] = "在自动物品条 4 上显示冷却转圈。",
  ["Shows cooldown swipes on auto item bar 5."] = "在自动物品条 5 上显示冷却转圈。",
  ["Shows how many of each item you carry on auto item bar 1."] = "在自动物品条 1 上显示你携带的每种物品数量。",
  ["Shows how many of each item you carry on auto item bar 2."] = "在自动物品条 2 上显示你携带的每种物品数量。",
  ["Shows how many of each item you carry on auto item bar 3."] = "在自动物品条 3 上显示你携带的每种物品数量。",
  ["Shows how many of each item you carry on auto item bar 4."] = "在自动物品条 4 上显示你携带的每种物品数量。",
  ["Shows how many of each item you carry on auto item bar 5."] = "在自动物品条 5 上显示你携带的每种物品数量。",
  ["The battle res button shows the group's shared charges and recharge timer (keys and boss fights) instead of the spell's own cooldown."] = "战复按钮显示团队共享的次数和充能计时（钥石和首领战），而非法术自身的冷却。",
  ["Tick the categories each auto item bar fills itself with, from your bags and gear. Rows run top to bottom in the order the buttons appear."] = "勾选每个自动物品条从你的背包和装备中自动填充的类别。各行从上到下即按钮出现的顺序。",
  ["Turns auto item bar 1 on. It fills itself with the categories ticked for it."] = "开启自动物品条 1。它会用为其勾选的类别自动填充。",
  ["Turns auto item bar 2 on. It fills itself with the categories ticked for it."] = "开启自动物品条 2。它会用为其勾选的类别自动填充。",
  ["Turns auto item bar 3 on. It fills itself with the categories ticked for it."] = "开启自动物品条 3。它会用为其勾选的类别自动填充。",
  ["Turns auto item bar 4 on. It fills itself with the categories ticked for it."] = "开启自动物品条 4。它会用为其勾选的类别自动填充。",
  ["Turns auto item bar 5 on. It fills itself with the categories ticked for it."] = "开启自动物品条 5。它会用为其勾选的类别自动填充。",
  ["Which way auto item bar 1 adds buttons."] = "自动物品条 1 添加按钮的方向。",
  ["Which way auto item bar 2 adds buttons."] = "自动物品条 2 添加按钮的方向。",
  ["Which way auto item bar 3 adds buttons."] = "自动物品条 3 添加按钮的方向。",
  ["Which way auto item bar 4 adds buttons."] = "自动物品条 4 添加按钮的方向。",
  ["Which way auto item bar 5 adds buttons."] = "自动物品条 5 添加按钮的方向。",
  ["Masque: Cooldown Manager icons"] = "Masque：冷却管理器图标",
  ["Masque: action bars"] = "Masque：动作条",
  ["Masque: auto item bars"] = "Masque：自动物品条",
  ["Masque: stance, pet, vehicle and item bar"] = "Masque：姿态条、宠物条、载具与物品条",
  ["With Masque installed, Cooldown Manager icons use the \"Phoenix UI: Cooldown Manager\" Masque group."] = "安装 Masque 后，冷却管理器图标使用 Masque 中的“Phoenix UI: Cooldown Manager”分组。",
  ["With Masque installed, Phoenix action bars use the skin you pick for each \"Phoenix UI: Action bar\" group in Masque."] = "安装 Masque 后，Phoenix 动作条使用你在 Masque 中为每个“Phoenix UI: Action bar”分组选择的皮肤。",
  ["With Masque installed, each auto item bar uses its own Masque group."] = "安装 Masque 后，每个自动物品条使用各自的 Masque 分组。",
  ["With Masque installed, the stance, pet, vehicle exit and item bars use their Masque groups."] = "安装 Masque 后，姿态条、宠物条、离开载具按钮和物品条使用各自的 Masque 分组。",
  ["Also track your own cooldowns."] = "同时追踪你自己的冷却。",
  ["Attach each member's icons to their Phoenix party frame, or show one movable list. Without Phoenix party frames the list is used."] = "将每名成员的图标附在其 Phoenix 小队框体上，或显示为一个可移动的列表。没有 Phoenix 小队框体时使用列表。",
  ["Battle res"] = "战复",
  ["Big damage cooldowns"] = "大型爆发技能",
  ["Bloodlust / Heroism"] = "嗜血 / 英勇",
  ["Distance between the party frame and its icons."] = "小队框体与其图标之间的距离。",
  ["Each member's class interrupt shows from the start; other spells appear once that member casts them."] = "每名成员的职业打断从一开始就显示；其他法术在该成员施放后出现。",
  ["Gap between party cooldown icons."] = "小队冷却图标之间的间隔。",
  ["Gap from the frame"] = "与框体的间距",
  ["Group defensives"] = "团队减伤",
  ["Icons per member"] = "每名成员图标数",
  ["Include yourself"] = "包括你自己",
  ["Interrupts"] = "打断",
  ["Most icons shown for one party member."] = "单个小队成员最多显示的图标数。",
  ["Party cooldowns"] = "小队冷却",
  ["Party interrupts, defensives, group cooldowns, battle res and Bloodlust as icons on the party frames or in a list (an OmniCD-style tracker)."] = "小队的打断、减伤、团队技能、战复和嗜血，以图标显示在小队框体上或列表中（OmniCD 风格的追踪器）。",
  ["Personal defensives"] = "个人减伤",
  ["Show interrupts before first use"] = "首次使用前显示打断",
  ["Side of the party frame"] = "小队框体的哪一侧",
  ["Size of the party cooldown icons."] = "小队冷却图标的大小。",
  ["Tracks Bloodlust, Heroism, Time Warp and Fury of the Aspects."] = "追踪 Bloodlust、Heroism、Time Warp 和 Fury of the Aspects。",
  ["Tracks battle res spells (Rebirth, Raise Ally, Soulstone, Intercession)."] = "追踪战复法术（Rebirth、Raise Ally、Soulstone、Intercession）。",
  ["Tracks big damage cooldowns such as Combustion, Avatar and Celestial Alignment."] = "追踪大型爆发技能，例如 Combustion、Avatar 和 Celestial Alignment。",
  ["Tracks group defensives such as Rallying Cry, Spirit Link Totem and Darkness."] = "追踪团队减伤，例如 Rallying Cry、Spirit Link Totem 和 Darkness。",
  ["Tracks party interrupts (Kick, Pummel, Counterspell, Wind Shear and the rest)."] = "追踪小队打断（Kick、Pummel、Counterspell、Wind Shear 等）。",
  ["Tracks personal defensives such as Ice Block, Divine Shield and Cloak of Shadows."] = "追踪个人减伤，例如 Ice Block、Divine Shield 和 Cloak of Shadows。",
  ["Where icons go"] = "图标位置",
  ["Which side of the party frame the icons sit on."] = "图标位于小队框体的哪一侧。",
  ["A compact, movable list of group loot rolls with item level, a timer bar and Need / Greed / Transmog / Pass buttons, in place of the game's roll frames."] = "紧凑、可移动的队伍拾取掷骰列表，带物品等级、计时条和需求 / 贪婪 / 幻化 / 放弃按钮，替代游戏自带的掷骰框体。",
  ["Height of each loot roll row (the icon and buttons follow)."] = "每行拾取掷骰的高度（图标和按钮随之调整）。",
